CREATE OR REPLACE FUNCTION public.zasp_runtime_lookup_acceptance(locator_value bytea, secret_value bytea, enrollment_value text, batch_value text, idempotency_value text, content_digest_value bytea, source_value text, media_value text, schema_value text, size_value bigint, count_value integer, job_value text, outbox_value text, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority jsonb;batch_row zasp_runtime_batch_authorities%ROWTYPE;scope_bytes bytea;expected_payload jsonb;response jsonb;now_value timestamptz;
BEGIN
 IF NOT COALESCE(zasp_discovery_principal_ready('zasp_runtime_ingest') AND zasp_production_runtime_acceptance_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime acceptance principal rejected';END IF;
 IF NOT COALESCE(octet_length(locator_value)=16 AND octet_length(secret_value)=32 AND enrollment_value ~ '^[0-9a-f]{64}$' AND zasp_valid_product_id(batch_value) AND length(idempotency_value) BETWEEN 16 AND 128 AND octet_length(content_digest_value)=32 AND source_value IN('tetragon','otlp') AND media_value='application/json' AND (schema_value='runtime-event-v1' OR schema_value='runtime-event-v2' AND source_value='tetragon') AND size_value BETWEEN 1 AND 67108864 AND count_value BETWEEN 1 AND 1000 AND zasp_valid_product_id(job_value) AND zasp_valid_product_id(outbox_value),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime acceptance input rejected';END IF;
 authority:=zasp_runtime_authenticate_sensor(locator_value,secret_value,'event-ingest');
 scope_bytes:=convert_to('zasp.sensor-enrollment.v1','UTF8')||decode('00','hex')||convert_to(authority->>'organization_id','UTF8')||decode('00','hex')||convert_to(authority->>'workspace_id','UTF8')||decode('00','hex')||convert_to(authority->>'environment_id','UTF8')||decode('00','hex')||convert_to(authority->>'sensor_id','UTF8');
 IF encode(digest(scope_bytes,'sha256'),'hex') IS DISTINCT FROM enrollment_value OR authority->>'sensor_kind' IS DISTINCT FROM source_value THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='runtime acceptance enrollment rejected';END IF;
 -- Do not wait on a batch while holding sensor authority. A worker may need
 -- that sensor lock; contention is a retry, never a reason to invert locks.
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities b WHERE (b.organization_id,b.workspace_id,b.environment_id,b.sensor_id,b.idempotency_key)=(authority->>'organization_id',authority->>'workspace_id',authority->>'environment_id',authority->>'sensor_id',idempotency_value) FOR SHARE NOWAIT;
 response:=jsonb_build_object('found',false);
 IF FOUND THEN
  IF (batch_row.batch_id,batch_row.content_digest,batch_row.source_kind,batch_row.payload_media_type,batch_row.payload_schema_version,batch_row.payload_size_bytes,batch_row.event_count) IS DISTINCT FROM (batch_value,content_digest_value,source_value,media_value,schema_value,size_value,count_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime acceptance conflict';END IF;
  IF batch_row.state NOT IN('uploading','unknown') THEN
   IF NOT COALESCE(batch_row.state IN('queued','processing','succeeded','failed','quarantined') AND batch_row.finalized_at IS NOT NULL AND batch_row.raw_artifact_checksum=content_digest_value AND batch_row.raw_artifact_size_bytes=size_value AND zasp_discovery_s3_object_reference(batch_row.raw_artifact_reference) AND right(batch_row.raw_artifact_reference,length(batch_row.raw_artifact_key)+1)='/'||batch_row.raw_artifact_key AND length(batch_row.raw_artifact_version_id) BETWEEN 1 AND 1024 AND batch_row.raw_artifact_version_id=btrim(batch_row.raw_artifact_version_id) AND batch_row.raw_artifact_kms_key ~ '^arn:aws:kms:[a-z0-9-]+:[0-9]{12}:key/[A-Za-z0-9-]{8,128}$',false) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime acceptance artifact rejected';END IF;
   expected_payload:=jsonb_build_object('batch_id',batch_row.batch_id,'job_id',job_value,'generation',batch_row.batch_generation,'pipeline_version',15,'artifact_reference',batch_row.raw_artifact_reference,'artifact_key',batch_row.raw_artifact_key,'artifact_version_id',batch_row.raw_artifact_version_id,'artifact_checksum',encode(batch_row.raw_artifact_checksum,'hex'),'artifact_size_bytes',batch_row.raw_artifact_size_bytes,'payload_media_type',batch_row.payload_media_type,'payload_schema_version',batch_row.payload_schema_version,'event_count',batch_row.event_count,'request_digest',encode(batch_row.request_digest,'hex'));
   IF NOT EXISTS(SELECT 1 FROM zasp_runtime_batches b WHERE (b.organization_id,b.workspace_id,b.environment_id,b.id,b.sensor_id,b.idempotency_key,b.payload_digest,b.event_count,b.payload_reference,b.payload_size_bytes,b.payload_media_type,b.payload_schema_version)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_value,batch_row.sensor_id,idempotency_value,content_digest_value,count_value,batch_row.raw_artifact_reference,size_value,media_value,schema_value))
   OR NOT EXISTS(SELECT 1 FROM zasp_discovery_jobs j WHERE (j.organization_id,j.workspace_id,j.environment_id,j.id,j.kind,j.authority_id,j.idempotency_key,j.request_digest)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,job_value,'runtime',batch_value,idempotency_value,batch_row.request_digest))
   OR NOT EXISTS(SELECT 1 FROM zasp_discovery_outbox o WHERE (o.organization_id,o.workspace_id,o.environment_id,o.id,o.topic,o.deterministic_key,o.payload_version,o.payload,o.payload_digest)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,outbox_value,'runtime-events','runtime:'||batch_value,15,expected_payload,digest(convert_to(expected_payload::text,'UTF8'),'sha256')))
   OR (SELECT count(*) FROM zasp_runtime_stage_work s WHERE (s.organization_id,s.workspace_id,s.environment_id,s.batch_id,s.batch_generation)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_value,batch_row.batch_generation) AND (s.stage,s.stage_order) IN(('archive',1),('index',2),('correlate',3),('project',4),('complete',5)))<>5
   THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime acceptance durable binding rejected';END IF;
   response:=jsonb_build_object('found',true,'batch_id',batch_row.batch_id,'generation',batch_row.batch_generation,'state',batch_row.state);
  END IF;
 END IF;
 -- Authentication locks are still held. Check wall time after the last query,
 -- not transaction start time, so lock waits cannot extend an expired token.
 IF NOT COALESCE(zasp_discovery_principal_ready('zasp_runtime_ingest') AND zasp_production_runtime_acceptance_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime acceptance principal expired';END IF;
 now_value:=clock_timestamp();
 IF NOT EXISTS(SELECT 1 FROM zasp_sensor_tokens t JOIN zasp_sensors s ON (s.organization_id,s.workspace_id,s.environment_id,s.id,s.version)=(t.organization_id,t.workspace_id,t.environment_id,t.sensor_id,t.sensor_version_at_issue) WHERE (t.organization_id,t.workspace_id,t.environment_id,t.sensor_id,t.id,t.token_generation)=(authority->>'organization_id',authority->>'workspace_id',authority->>'environment_id',authority->>'sensor_id',authority->>'token_id',(authority->>'token_generation')::bigint) AND t.revoked_at IS NULL AND t.expires_at>now_value AND s.state IN('pending','active','degraded')) THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='runtime acceptance credential expired';END IF;
 RETURN response;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_candidate_lineage_valid(value jsonb, event_time_value timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE identifier text;key_value text;start_value timestamptz;
BEGIN
 IF value IS NULL OR jsonb_typeof(value)<>'object' OR event_time_value IS NULL OR value->>'profile' IS DISTINCT FROM 'kubernetes-container-v1' OR octet_length(value::text)>1024 THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(value) member WHERE member.key NOT IN('profile','cluster_uid','node_uid','boot_id','pod_uid','container_id','process_id','process_start_time','cgroup_id') OR jsonb_typeof(member.value)<>'string' OR member.value='""'::jsonb) THEN RETURN false;END IF;
 FOREACH key_value IN ARRAY ARRAY['cluster_uid','node_uid','boot_id','pod_uid'] LOOP
  identifier:=value->>key_value;
  IF NOT COALESCE(identifier ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND identifier<>'00000000-0000-0000-0000-000000000000',false) THEN RETURN false;END IF;
 END LOOP;
 IF NOT COALESCE(value->>'container_id' ~ '^(containerd|docker|cri-o)://[0-9a-f]{64}$' AND right(value->>'container_id',64)<>repeat('0',64),false) THEN RETURN false;END IF;
 IF (value ? 'process_id') IS DISTINCT FROM (value ? 'process_start_time') THEN RETURN false;END IF;
 IF value ? 'process_id' THEN
  IF value->>'process_id' !~ '^[1-9][0-9]{0,9}$' OR (value->>'process_id')::numeric>4294967295 THEN RETURN false;END IF;
  IF value->>'process_start_time' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,9})?Z$' THEN RETURN false;END IF;
  start_value:=(value->>'process_start_time')::timestamptz;
  IF start_value<='1970-01-01T00:00:00Z'::timestamptz OR start_value>event_time_value THEN RETURN false;END IF;
 END IF;
 IF value ? 'cgroup_id' AND (value->>'cgroup_id' !~ '^[1-9][0-9]{0,19}$' OR (value->>'cgroup_id')::numeric>18446744073709551615) THEN RETURN false;END IF;
 RETURN true;
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow OR invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_freeze_candidates(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text, attempt_value integer, implementation_value text, input_digest_value bytea, index_receipt_value bytea, archive_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE work_row zasp_runtime_stage_work%ROWTYPE;batch_row zasp_runtime_batch_authorities%ROWTYPE;domain_row zasp_runtime_batch_domains%ROWTYPE;index_row zasp_runtime_stage_work%ROWTYPE;prior zasp_runtime_candidate_snapshots%ROWTYPE;
 receipt jsonb;archive jsonb;event_value jsonb;ordinal_value bigint;archive_digest_value bytea;receipt_digest_value bytea;now_value timestamptz;candidate_values jsonb;body_value bytea;body_digest bytea;possible_count integer;
BEGIN
 IF NOT COALESCE(zasp_runtime_principal_ready('zasp_runtime_correlation_worker') AND zasp_runtime_stage_for_session()='correlate',false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime candidate principal rejected';END IF;
 IF NOT COALESCE(zasp_valid_product_id(organization_value) AND zasp_valid_product_id(workspace_value) AND zasp_valid_product_id(environment_value) AND zasp_valid_product_id(batch_value) AND generation_value>0 AND worker_value ~ '^[a-z][a-z0-9.-]{2,127}$' AND lease_token_value ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' AND attempt_value BETWEEN 1 AND 100 AND implementation_value='runtime-correlation-v2' AND octet_length(input_digest_value)=32 AND octet_length(index_receipt_value) BETWEEN 1 AND 1048576 AND octet_length(archive_value) BETWEEN 1 AND 67108864,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime candidate input rejected';END IF;
 SELECT * INTO work_row FROM zasp_runtime_stage_work WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,stage)=(organization_value,workspace_value,environment_value,batch_value,generation_value,'correlate') FOR UPDATE;
 now_value:=clock_timestamp();
 IF NOT FOUND OR work_row.state<>'leased' OR work_row.lease_owner IS DISTINCT FROM worker_value OR work_row.lease_token IS DISTINCT FROM lease_token_value OR work_row.attempt IS DISTINCT FROM attempt_value OR work_row.implementation_version IS DISTINCT FROM implementation_value OR work_row.input_digest IS DISTINCT FROM input_digest_value OR work_row.lease_expires_at<=now_value THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime candidate lease missing';END IF;
 SELECT * INTO STRICT batch_row FROM zasp_runtime_batch_authorities WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value);
 SELECT * INTO STRICT domain_row FROM zasp_runtime_batch_domains WHERE (organization_id,workspace_id,environment_id,batch_id,generation,source_sensor_id,source_kind)=(organization_value,workspace_value,environment_value,batch_value,generation_value,batch_row.sensor_id,batch_row.source_kind);
 SELECT * INTO STRICT index_row FROM zasp_runtime_stage_work WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,stage,state)=(organization_value,workspace_value,environment_value,batch_value,generation_value,'index','succeeded');
 archive_digest_value:=digest(archive_value,'sha256');receipt_digest_value:=digest(index_receipt_value,'sha256');
 IF batch_row.state<>'processing' OR batch_row.raw_artifact_checksum IS DISTINCT FROM archive_digest_value OR batch_row.content_digest IS DISTINCT FROM archive_digest_value OR batch_row.raw_artifact_size_bytes IS DISTINCT FROM octet_length(archive_value)::bigint OR index_row.result_digest IS DISTINCT FROM receipt_digest_value OR index_row.effect_digest IS DISTINCT FROM input_digest_value OR work_row.predecessor_digest IS DISTINCT FROM index_row.effect_digest OR index_row.input_digest IS DISTINCT FROM archive_digest_value OR index_row.predecessor_digest IS DISTINCT FROM archive_digest_value THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime candidate predecessor rejected';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_runtime_stage_work WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,stage,state,effect_digest,result_reference,result_version_id)=(organization_value,workspace_value,environment_value,batch_value,generation_value,'archive','succeeded',archive_digest_value,batch_row.raw_artifact_reference,batch_row.raw_artifact_version_id)) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime candidate archive predecessor rejected';END IF;
 receipt:=convert_from(index_receipt_value,'UTF8')::jsonb;archive:=convert_from(archive_value,'UTF8')::jsonb;
 IF NOT COALESCE(receipt->>'schema'='runtime-stage-receipt-v1' AND receipt->>'stage'='index' AND receipt->>'implementation_version'='runtime-index-v1' AND receipt->>'organization_id'=organization_value AND receipt->>'workspace_id'=workspace_value AND receipt->>'environment_id'=environment_value AND receipt->>'batch_id'=batch_value AND receipt->>'generation'=generation_value::text AND receipt->>'effect_digest'=encode(input_digest_value,'hex') AND receipt->>'archive_digest'=encode(archive_digest_value,'hex') AND receipt->>'archive_reference'=batch_row.raw_artifact_reference AND receipt->>'archive_version_id'=batch_row.raw_artifact_version_id AND receipt->>'input_digest'=encode(archive_digest_value,'hex') AND receipt->>'input_reference'=batch_row.raw_artifact_reference AND receipt->>'input_version_id'=batch_row.raw_artifact_version_id AND archive->>'source'=domain_row.source_kind AND jsonb_typeof(archive->'events')='array' AND jsonb_array_length(archive->'events')=batch_row.event_count,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime candidate archive binding rejected';END IF;
 SELECT * INTO prior FROM zasp_runtime_candidate_snapshots WHERE (organization_id,workspace_id,environment_id,batch_id,generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value);
 IF FOUND THEN
  IF prior.archive_digest IS DISTINCT FROM archive_digest_value OR prior.index_receipt_digest IS DISTINCT FROM receipt_digest_value THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime candidate replay conflict';END IF;
  PERFORM zasp_runtime_candidate_execution_live(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,lease_token_value,attempt_value,implementation_value,input_digest_value,archive_digest_value,receipt_digest_value);
  RETURN jsonb_build_object('snapshot',encode(prior.snapshot_body,'hex'),'sha256',encode(prior.snapshot_digest,'hex'),'replayed',true);
 END IF;
 -- Only the two admission identities are locked. Existing candidate identities
 -- are sampled in the selection statement; a later revocation cannot rewrite
 -- an already frozen historical decision. Never lock another batch's stage.
 PERFORM id FROM zasp_sensors WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND id IN(domain_row.source_sensor_id,domain_row.runtime_sensor_id) ORDER BY id FOR SHARE;
 now_value:=clock_timestamp();
 IF work_row.lease_expires_at<=now_value OR NOT zasp_runtime_principal_ready('zasp_runtime_correlation_worker') OR NOT EXISTS(SELECT 1 FROM zasp_sensors WHERE (organization_id,workspace_id,environment_id,id,kind,state)=(organization_value,workspace_value,environment_value,domain_row.source_sensor_id,domain_row.source_kind,'active') AND revoked_at IS NULL) OR domain_row.runtime_sensor_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM zasp_sensors WHERE (organization_id,workspace_id,environment_id,id,kind,state)=(organization_value,workspace_value,environment_value,domain_row.runtime_sensor_id,'tetragon','active') AND revoked_at IS NULL) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime candidate enrollment rejected';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_runtime_deliveries WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,disposition)=(organization_value,workspace_value,environment_value,batch_value,generation_value,'held') AND lease_expires_at>now_value AND visibility_deadline>now_value) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime candidate delivery missing';END IF;
 FOR event_value,ordinal_value IN SELECT value,ordinality FROM jsonb_array_elements(archive->'events') WITH ORDINALITY LOOP
  IF event_value ? 'observed_lineage' AND NOT zasp_runtime_candidate_lineage_valid(event_value->'observed_lineage',(event_value->>'event_time')::timestamptz) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime candidate lineage rejected';END IF;
  IF domain_row.source_kind='otlp' AND domain_row.runtime_sensor_id IS NOT NULL AND event_value ? 'observed_lineage' THEN
   INSERT INTO zasp_runtime_candidate_observations(organization_id,workspace_id,environment_id,batch_id,generation,event_ordinal,source_sensor_id,runtime_sensor_id,archive_digest,index_receipt_digest,agent_id,session_id,observed_lineage,event_time,cluster_uid,node_uid,boot_id,pod_uid,container_id)
   VALUES(organization_value,workspace_value,environment_value,batch_value,generation_value,ordinal_value,domain_row.source_sensor_id,domain_row.runtime_sensor_id,archive_digest_value,receipt_digest_value,event_value#>>'{attributes,agent.id}',event_value#>>'{attributes,session.id}',event_value->'observed_lineage',(event_value->>'event_time')::timestamptz,event_value#>>'{observed_lineage,cluster_uid}',event_value#>>'{observed_lineage,node_uid}',event_value#>>'{observed_lineage,boot_id}',event_value#>>'{observed_lineage,pod_uid}',event_value#>>'{observed_lineage,container_id}');
  END IF;
 END LOOP;
 -- Fixed five-minute event-time profile. At most 1,001 indexed observations
 -- per input event; an overflowing union fails closed rather than truncating.
 WITH targets AS MATERIALIZED (SELECT DISTINCT value->'observed_lineage' lineage,(value->>'event_time')::timestamptz event_time FROM jsonb_array_elements(archive->'events') WHERE value ? 'observed_lineage'),
 possible AS MATERIALIZED (
  SELECT selected.* FROM targets target CROSS JOIN LATERAL (
   SELECT observation.batch_id,observation.event_ordinal FROM zasp_runtime_candidate_observations observation
   WHERE (observation.organization_id,observation.workspace_id,observation.environment_id,observation.runtime_sensor_id,observation.cluster_uid,observation.node_uid,observation.boot_id,observation.pod_uid,observation.container_id)=(organization_value,workspace_value,environment_value,domain_row.runtime_sensor_id,target.lineage->>'cluster_uid',target.lineage->>'node_uid',target.lineage->>'boot_id',target.lineage->>'pod_uid',target.lineage->>'container_id')
    AND observation.event_time BETWEEN target.event_time-interval '5 minutes' AND target.event_time+interval '5 minutes'
   ORDER BY observation.event_time,observation.batch_id,observation.event_ordinal LIMIT 1001
  ) selected
 ), unique_rows AS MATERIALIZED (SELECT DISTINCT * FROM possible), selected AS (
  SELECT observation.* FROM unique_rows occurrence
  JOIN zasp_runtime_candidate_observations observation ON (observation.organization_id,observation.workspace_id,observation.environment_id,observation.batch_id,observation.event_ordinal)=(organization_value,workspace_value,environment_value,occurrence.batch_id,occurrence.event_ordinal)
  JOIN zasp_sensors source ON (source.organization_id,source.workspace_id,source.environment_id,source.id,source.kind,source.state)=(observation.organization_id,observation.workspace_id,observation.environment_id,observation.source_sensor_id,'otlp','active') AND source.revoked_at IS NULL
  JOIN zasp_runtime_batch_authorities origin ON (origin.organization_id,origin.workspace_id,origin.environment_id,origin.batch_id,origin.batch_generation)=(observation.organization_id,observation.workspace_id,observation.environment_id,observation.batch_id,observation.generation) AND origin.state IN('processing','succeeded')
  ORDER BY observation.batch_id,observation.event_ordinal LIMIT 1001
 ) SELECT COALESCE(jsonb_agg(jsonb_build_object('batch_id',batch_id,'generation',generation,'event_ordinal',event_ordinal,'source_sensor_id',source_sensor_id,'agent_id',agent_id,'session_id',session_id,'archive_digest',encode(archive_digest,'hex'),'index_receipt_digest',encode(index_receipt_digest,'hex'),'observed_lineage',observed_lineage,'event_time',to_char(event_time AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) ORDER BY batch_id,event_ordinal),'[]'::jsonb),(SELECT count(*) FROM (SELECT 1 FROM unique_rows LIMIT 1001) bounded)
 INTO candidate_values,possible_count FROM selected;
 -- Detect overflow BEFORE authority filtering: revoked/failed rows must never
 -- occupy the internal bound and hide another viable identity beyond it.
 IF possible_count>1000 OR jsonb_array_length(candidate_values)>1000 THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='runtime candidate snapshot overflow';END IF;
 body_value:=convert_to(jsonb_build_object('schema','runtime-candidate-snapshot-v1','organization_id',organization_value,'workspace_id',workspace_value,'environment_id',environment_value,'batch_id',batch_value,'generation',generation_value,'source_sensor_id',domain_row.source_sensor_id,'runtime_sensor_id',domain_row.runtime_sensor_id,'archive_digest',encode(archive_digest_value,'hex'),'index_receipt_digest',encode(receipt_digest_value,'hex'),'window_seconds',300,'candidates',candidate_values)::text,'UTF8');
 body_digest:=digest(body_value,'sha256');
 IF clock_timestamp()>=work_row.lease_expires_at THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime candidate lease expired';END IF;
 INSERT INTO zasp_runtime_candidate_snapshots(organization_id,workspace_id,environment_id,batch_id,generation,source_sensor_id,source_kind,runtime_sensor_id,archive_digest,index_receipt_digest,snapshot_body,snapshot_digest)
 VALUES(organization_value,workspace_value,environment_value,batch_value,generation_value,domain_row.source_sensor_id,domain_row.source_kind,domain_row.runtime_sensor_id,archive_digest_value,receipt_digest_value,body_value,body_digest);
 PERFORM zasp_runtime_candidate_execution_live(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,lease_token_value,attempt_value,implementation_value,input_digest_value,archive_digest_value,receipt_digest_value);
 RETURN jsonb_build_object('snapshot',encode(body_value,'hex'),'sha256',encode(body_digest,'hex'),'replayed',false);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_claim_stage_compatible(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer, allow_v2 boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE stage_value text;authority_value text;result_value jsonb;prior_capability text;
BEGIN
 stage_value:=zasp_runtime_stage_for_session();
 IF worker_value IS NULL OR lease_token_value IS NULL OR lease_seconds IS NULL OR claim_limit IS NULL OR allow_v2 IS NULL OR (allow_v2 AND stage_value<>'correlate') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime routing capability rejected';END IF;
 authority_value:=CASE stage_value WHEN 'archive' THEN 'zasp_runtime_archive_worker' WHEN 'index' THEN 'zasp_runtime_index_worker' WHEN 'correlate' THEN 'zasp_runtime_correlation_worker' WHEN 'project' THEN 'zasp_runtime_projection_worker' WHEN 'complete' THEN 'zasp_runtime_coordinator' END;
 IF stage_value IS NULL OR NOT zasp_runtime_principal_ready(authority_value) OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime stage authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp-runtime-stage-claim:'||stage_value,0));
 prior_capability:=COALESCE(current_setting('zasp.runtime_correlation_claim_version',true),'');
 PERFORM set_config('zasp.runtime_correlation_claim_version',CASE WHEN allow_v2 THEN 'runtime-correlation-v2' ELSE 'runtime-correlation-v1' END,true);
 WITH exhausted AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='failed',last_error_class='exhausted',completed_at=transaction_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_heartbeat_at=NULL,
   completion_digest=digest(convert_to(concat_ws(chr(31),stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation::text,stage_row.stage,stage_row.attempt::text,'exhausted'),'UTF8'),'sha256'),
   completion_result=jsonb_build_object('batch_id',stage_row.batch_id,'generation',stage_row.batch_generation,'stage',stage_row.stage,'state','failed','attempt',stage_row.attempt,'error_class','exhausted')
  WHERE stage_row.stage=stage_value AND (stage_value NOT IN('archive','index') OR stage_value='archive' AND stage_row.implementation_version='runtime-archive-v1' OR stage_value='index' AND stage_row.implementation_version='runtime-index-v1') AND (stage_value NOT IN('project','complete') OR stage_value='project' AND stage_row.implementation_version='runtime-projection-v1' OR stage_value='complete' AND stage_row.implementation_version='runtime-complete-v1') AND (stage_value<>'correlate' OR stage_row.implementation_version='runtime-correlation-v1' OR allow_v2 AND stage_row.implementation_version='runtime-correlation-v2') AND stage_row.attempt>=100 AND stage_row.state IN('pending','retryable','leased') AND (stage_row.state<>'leased' OR stage_row.lease_expires_at<=transaction_timestamp())
  RETURNING stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.completion_digest,stage_row.completion_result
 ),failed_batches AS (
  UPDATE zasp_runtime_batch_authorities authority_row SET state='failed',completed_at=transaction_timestamp(),completion_digest=exhausted.completion_digest,completion_result=exhausted.completion_result
  FROM exhausted WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(exhausted.organization_id,exhausted.workspace_id,exhausted.environment_id,exhausted.batch_id)
  RETURNING authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.completion_digest,authority_row.completion_result
 ),failed_legacy_batches AS (
  UPDATE zasp_runtime_batches batch_row SET state='failed',completed_at=transaction_timestamp()
  FROM failed_batches WHERE (batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id)
  RETURNING batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id
 ),failed_jobs AS (
  UPDATE zasp_discovery_jobs job_row SET state='failed',last_error='exhausted',completed_at=transaction_timestamp(),updated_at=transaction_timestamp(),completion_digest=failed_batches.completion_digest,completion_result=failed_batches.completion_result
  FROM failed_batches WHERE (job_row.organization_id,job_row.workspace_id,job_row.environment_id,job_row.kind,job_row.authority_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,'runtime',failed_batches.batch_id)
  RETURNING job_row.organization_id
 )
 UPDATE zasp_runtime_deliveries delivery_row SET disposition='ack_pending',updated_at=transaction_timestamp()
 FROM failed_batches WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id) AND delivery_row.disposition='held';
 WITH eligible AS (
  SELECT stage_row.ctid row_id,stage_row.*,row_number() OVER(PARTITION BY stage_row.organization_id ORDER BY stage_row.available_at,stage_row.batch_id) organization_rank
  FROM zasp_runtime_stage_work stage_row
  WHERE stage_row.stage=stage_value AND (stage_value NOT IN('archive','index') OR stage_value='archive' AND stage_row.implementation_version='runtime-archive-v1' OR stage_value='index' AND stage_row.implementation_version='runtime-index-v1') AND (stage_value NOT IN('project','complete') OR stage_value='project' AND stage_row.implementation_version='runtime-projection-v1' OR stage_value='complete' AND stage_row.implementation_version='runtime-complete-v1') AND (stage_value<>'correlate' OR stage_row.implementation_version='runtime-correlation-v1' OR allow_v2 AND stage_row.implementation_version='runtime-correlation-v2') AND stage_row.attempt<100 AND stage_row.available_at<=transaction_timestamp() AND (stage_row.state IN('pending','retryable') OR stage_row.state='leased' AND stage_row.lease_expires_at<=transaction_timestamp())
   AND stage_row.input_digest IS NOT NULL
   AND EXISTS(SELECT 1 FROM zasp_runtime_deliveries delivery_row WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id,delivery_row.batch_generation,delivery_row.disposition)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation,'held') AND delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp())
   AND (stage_row.stage_order=1 OR EXISTS(SELECT 1 FROM zasp_runtime_stage_work predecessor WHERE (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order,predecessor.state,predecessor.effect_digest)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage_order-1,'succeeded',stage_row.predecessor_digest)))
   AND NOT EXISTS(SELECT 1 FROM zasp_runtime_stage_work live_row WHERE live_row.stage=stage_value AND live_row.organization_id=stage_row.organization_id AND live_row.state='leased' AND live_row.lease_expires_at>transaction_timestamp())
 ),organizations AS (
  SELECT eligible.organization_id,min(eligible.available_at) first_available,MAX(fairness.last_claimed_at) last_claimed_at
  FROM eligible LEFT JOIN zasp_runtime_stage_fairness fairness ON (fairness.stage,fairness.organization_id)=(stage_value,eligible.organization_id)
  WHERE eligible.organization_rank=1 GROUP BY eligible.organization_id
  ORDER BY MAX(fairness.last_claimed_at) NULLS FIRST,min(eligible.available_at),eligible.organization_id LIMIT claim_limit
 ),candidates AS (
  SELECT stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage
  FROM zasp_runtime_stage_work stage_row JOIN eligible ON stage_row.ctid=eligible.row_id JOIN organizations ON organizations.organization_id=eligible.organization_id
  WHERE eligible.organization_rank=1 ORDER BY organizations.last_claimed_at NULLS FIRST,organizations.first_available,stage_row.organization_id,stage_row.batch_id FOR UPDATE OF stage_row SKIP LOCKED
 ),claimed AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='leased',attempt=stage_row.attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),last_heartbeat_at=transaction_timestamp(),last_error_class=NULL
  FROM candidates WHERE (stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage)=(candidates.organization_id,candidates.workspace_id,candidates.environment_id,candidates.batch_id,candidates.stage)
  RETURNING stage_row.*
 ),fairness AS (
  INSERT INTO zasp_runtime_stage_fairness(stage,organization_id,last_claimed_at) SELECT stage_value,claimed.organization_id,transaction_timestamp() FROM claimed
  ON CONFLICT(stage,organization_id) DO UPDATE SET last_claimed_at=excluded.last_claimed_at RETURNING organization_id
 )
 SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',claimed.organization_id,'workspace_id',claimed.workspace_id,'environment_id',claimed.environment_id,'batch_id',claimed.batch_id,'generation',claimed.batch_generation,'stage',claimed.stage,'attempt',claimed.attempt,'implementation_version',claimed.implementation_version,'predecessor_digest',CASE WHEN claimed.predecessor_digest IS NULL THEN NULL ELSE encode(claimed.predecessor_digest,'hex') END,'input_digest',encode(claimed.input_digest,'hex'),'input_reference',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_reference ELSE predecessor.result_reference END,'input_version_id',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_version_id ELSE predecessor.result_version_id END,'lease_expires_at',claimed.lease_expires_at) ORDER BY claimed.organization_id,claimed.batch_id),'[]'::jsonb) INTO result_value
 FROM claimed JOIN zasp_runtime_batch_authorities authority_row ON (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.batch_generation)
 LEFT JOIN zasp_runtime_stage_work predecessor ON (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.stage_order-1);
 IF stage_value='archive' AND jsonb_array_length(result_value)>0 THEN UPDATE zasp_runtime_batch_authorities authority_row SET state='processing' WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(result_value) item WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(item->>'organization_id',item->>'workspace_id',item->>'environment_id',item->>'batch_id'));END IF;
 PERFORM set_config('zasp.runtime_correlation_claim_version',prior_capability,true);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_public_create_sensor(organization_value text, workspace_value text, environment_value text, principal_value text, sensor_value text, name_value text, kind_value text, mode_value text, idempotency_value text, request_digest_value bytea, token_value text, generation_value bigint, locator_digest_value bytea, salt_value bytea, token_hash_value bytea, expires_value timestamp with time zone, runtime_sensor_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior_value zasp_runtime_sensor_mutations%ROWTYPE;result_value jsonb;stored_runtime text;
BEGIN
 IF runtime_sensor_value IS NOT NULL AND NOT COALESCE(kind_value='otlp' AND zasp_valid_product_id(runtime_sensor_value) AND runtime_sensor_value<>sensor_value,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='sensor pairing rejected';END IF;
 IF runtime_sensor_value IS NOT NULL AND NOT COALESCE(zasp_discovery_principal_ready('zasp_discovery_api') AND EXISTS(SELECT 1 FROM zasp_identity_admin_effective_scopes(principal_value,organization_value) effective WHERE (effective.organization_id,effective.workspace_id,effective.environment_id)=(organization_value,workspace_value,environment_value) AND effective.permissions ? 'manage_workflows'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='sensor pairing authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,principal_value,'createSensorEnrollment',idempotency_value),0));
 IF runtime_sensor_value IS NOT NULL AND NOT EXISTS(SELECT 1 FROM zasp_identity_admin_effective_scopes(principal_value,organization_value) effective WHERE (effective.organization_id,effective.workspace_id,effective.environment_id)=(organization_value,workspace_value,environment_value) AND effective.permissions ? 'manage_workflows') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='sensor pairing authority rejected';END IF;
 SELECT * INTO prior_value FROM zasp_runtime_sensor_mutations WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(organization_value,workspace_value,environment_value,principal_value,'createSensorEnrollment',idempotency_value) FOR UPDATE;
 IF FOUND THEN
  -- Receipt row locking can independently wait after the advisory lock.
  IF runtime_sensor_value IS NOT NULL AND NOT EXISTS(SELECT 1 FROM zasp_identity_admin_effective_scopes(principal_value,organization_value) effective WHERE (effective.organization_id,effective.workspace_id,effective.environment_id)=(organization_value,workspace_value,environment_value) AND effective.permissions ? 'manage_workflows') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='sensor pairing authority rejected';END IF;
  SELECT runtime_sensor_id INTO stored_runtime FROM zasp_runtime_sensor_pairings WHERE (organization_id,workspace_id,environment_id,sensor_id)=(organization_value,workspace_value,environment_value,prior_value.sensor_id);
  IF prior_value.request_digest IS DISTINCT FROM request_digest_value OR stored_runtime IS DISTINCT FROM runtime_sensor_value
   OR prior_value.result#>>'{body,id}' IS DISTINCT FROM prior_value.sensor_id OR prior_value.result#>>'{body,runtime_sensor_id}' IS DISTINCT FROM stored_runtime
   OR prior_value.result#>>'{body,name}' IS DISTINCT FROM name_value OR prior_value.result#>>'{body,kind}' IS DISTINCT FROM kind_value OR prior_value.result#>>'{body,mode}' IS DISTINCT FROM mode_value THEN
   RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='sensor pairing replay conflict';
  END IF;
  RETURN jsonb_set(prior_value.result,'{replayed}','true'::jsonb);
 END IF;
 IF runtime_sensor_value IS NOT NULL THEN
  -- FOR SHARE conflicts with status updates; KEY SHARE would not fence revoke.
  PERFORM 1 FROM zasp_sensors WHERE (organization_id,workspace_id,environment_id,id)=(organization_value,workspace_value,environment_value,runtime_sensor_value) AND kind='tetragon' AND state='active' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime sensor pairing anchor missing';END IF;
  -- Permission may have changed while waiting for the anchor or idempotency lock.
  IF NOT EXISTS(SELECT 1 FROM zasp_identity_admin_effective_scopes(principal_value,organization_value) effective WHERE (effective.organization_id,effective.workspace_id,effective.environment_id)=(organization_value,workspace_value,environment_value) AND effective.permissions ? 'manage_workflows') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='sensor pairing authority rejected';END IF;
 END IF;
 result_value:=zasp_runtime_public_create_sensor_v44(organization_value,workspace_value,environment_value,principal_value,sensor_value,name_value,kind_value,mode_value,idempotency_value,request_digest_value,token_value,generation_value,locator_digest_value,salt_value,token_hash_value,expires_value);
 IF result_value->>'replayed' IS DISTINCT FROM 'false' OR result_value#>>'{body,id}' IS DISTINCT FROM sensor_value THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='sensor pairing creation conflict';END IF;
 IF runtime_sensor_value IS NOT NULL THEN
  -- The legacy creation path may have waited on credential uniqueness locks.
  IF NOT EXISTS(SELECT 1 FROM zasp_identity_admin_effective_scopes(principal_value,organization_value) effective WHERE (effective.organization_id,effective.workspace_id,effective.environment_id)=(organization_value,workspace_value,environment_value) AND effective.permissions ? 'manage_workflows') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='sensor pairing authority rejected';END IF;
  INSERT INTO zasp_runtime_sensor_pairings(organization_id,workspace_id,environment_id,sensor_id,runtime_sensor_id) VALUES(organization_value,workspace_value,environment_value,sensor_value,runtime_sensor_value);
  result_value:=jsonb_set(result_value,'{body,runtime_sensor_id}',to_jsonb(runtime_sensor_value));
  UPDATE zasp_runtime_sensor_mutations SET result=result_value WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,sensor_id)=(organization_value,workspace_value,environment_value,principal_value,'createSensorEnrollment',idempotency_value,sensor_value) AND request_digest=request_digest_value;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='sensor pairing receipt missing';END IF;
 END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_bind_batch_domain()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE runtime_value text;
BEGIN
 IF NEW.source_kind='tetragon' THEN runtime_value:=NEW.sensor_id;
 ELSIF NEW.source_kind='otlp' THEN
  SELECT runtime_sensor_id INTO runtime_value FROM zasp_runtime_sensor_pairings WHERE (organization_id,workspace_id,environment_id,sensor_id)=(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.sensor_id);
 ELSE RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime batch source rejected';END IF;
 INSERT INTO zasp_runtime_batch_domains(organization_id,workspace_id,environment_id,batch_id,generation,source_sensor_id,source_kind,runtime_sensor_id)
 VALUES(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.batch_id,NEW.batch_generation,NEW.sensor_id,NEW.source_kind,runtime_value);
 RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_public_create_sensor_v44(organization_value text, workspace_value text, environment_value text, principal_value text, sensor_value text, name_value text, kind_value text, mode_value text, idempotency_value text, request_digest_value bytea, token_value text, generation_value bigint, locator_digest_value bytea, salt_value bytea, token_hash_value bytea, expires_value timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior_value zasp_runtime_sensor_mutations%ROWTYPE;result_value jsonb;
BEGIN
 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(principal_value) OR NOT zasp_valid_product_id(sensor_value) OR NOT zasp_valid_product_id(token_value) OR length(name_value) NOT BETWEEN 1 AND 128 OR name_value<>btrim(name_value) OR name_value ~ '[[:cntrl:]]' OR kind_value NOT IN('tetragon','otlp') OR mode_value NOT IN('metadata_only','full') OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR octet_length(request_digest_value)<>32 OR generation_value<>1 OR octet_length(locator_digest_value)<>32 OR octet_length(salt_value)<>32 OR octet_length(token_hash_value)<>32 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='sensor mutation rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,principal_value,'createSensorEnrollment',idempotency_value),0));
 SELECT * INTO prior_value FROM zasp_runtime_sensor_mutations mutation WHERE (mutation.organization_id,mutation.workspace_id,mutation.environment_id,mutation.principal_id,mutation.operation,mutation.idempotency_key)=(organization_value,workspace_value,environment_value,principal_value,'createSensorEnrollment',idempotency_value);
 IF FOUND THEN IF prior_value.request_digest IS DISTINCT FROM request_digest_value THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='sensor mutation conflict';END IF;RETURN jsonb_set(prior_value.result,'{replayed}','true'::jsonb);END IF;
 IF EXISTS(SELECT 1 FROM zasp_sensors sensor_row WHERE (sensor_row.organization_id,sensor_row.workspace_id,sensor_row.environment_id,sensor_row.id)=(organization_value,workspace_value,environment_value,sensor_value)) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='sensor mutation conflict';END IF;
 INSERT INTO zasp_sensors(organization_id,workspace_id,environment_id,id,name,kind,mode) VALUES(organization_value,workspace_value,environment_value,sensor_value,name_value,kind_value,mode_value);
 PERFORM zasp_runtime_issue_sensor_token(organization_value,workspace_value,environment_value,sensor_value,token_value,generation_value,1,locator_digest_value,salt_value,token_hash_value,expires_value);
 result_value:=jsonb_build_object('body',zasp_runtime_public_sensor_value(organization_value,workspace_value,environment_value,sensor_value),'token_id',token_value,'token_generation',generation_value,'token_expires_at',to_char(expires_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'replayed',false);
 INSERT INTO zasp_runtime_sensor_mutations(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,request_digest,sensor_id,expected_version,token_id,token_generation,result) VALUES(organization_value,workspace_value,environment_value,principal_value,'createSensorEnrollment',idempotency_value,request_digest_value,sensor_value,0,token_value,generation_value,result_value);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_commit_reserved_batch(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, request_digest_value bytea, job_value text, outbox_value text, artifact_reference_value text, artifact_key_value text, artifact_version_value text, artifact_checksum_value bytea, artifact_size_value bigint, artifact_kms_key_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE batch_row zasp_runtime_batch_authorities%ROWTYPE;event_payload jsonb;result_value jsonb;
BEGIN
 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(batch_value) OR generation_value<1 OR octet_length(request_digest_value)<>32 OR NOT zasp_valid_product_id(job_value) OR NOT zasp_valid_product_id(outbox_value) OR NOT zasp_discovery_s3_object_reference(artifact_reference_value) OR length(artifact_key_value) NOT BETWEEN 32 AND 1024 OR right(artifact_reference_value,length(artifact_key_value)+1)<>'/'||artifact_key_value OR length(artifact_version_value) NOT BETWEEN 1 AND 1024 OR artifact_version_value<>btrim(artifact_version_value) OR octet_length(artifact_checksum_value)<>32 OR artifact_size_value NOT BETWEEN 1 AND 67108864 OR artifact_kms_key_value !~ '^arn:aws:kms:[a-z0-9-]+:[0-9]{12}:key/[A-Za-z0-9-]{8,128}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime batch rejected';END IF;
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation,authority_row.request_digest)=(organization_value,workspace_value,environment_value,batch_value,generation_value,request_digest_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime batch rejected';END IF;
 IF batch_row.payload_schema_version='runtime-event-v2' AND batch_row.source_kind<>'tetragon' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime precision source rejected';END IF;
IF batch_row.payload_schema_version='runtime-event-v2' OR batch_row.source_kind='otlp' AND batch_row.payload_schema_version='runtime-event-v1' THEN PERFORM zasp_runtime_precision_transport_ready();END IF;
 IF batch_row.state NOT IN('uploading','unknown') THEN
  IF batch_row.state IN('queued','processing','succeeded','failed','quarantined') AND (batch_row.raw_artifact_reference,batch_row.raw_artifact_key,batch_row.raw_artifact_version_id,batch_row.raw_artifact_checksum,batch_row.raw_artifact_size_bytes,batch_row.raw_artifact_kms_key) IS NOT DISTINCT FROM (artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value)
   AND EXISTS(SELECT 1 FROM zasp_discovery_jobs job_row WHERE (job_row.organization_id,job_row.workspace_id,job_row.environment_id,job_row.id,job_row.kind,job_row.authority_id)=(organization_value,workspace_value,environment_value,job_value,'runtime',batch_value))
   AND EXISTS(SELECT 1 FROM zasp_discovery_outbox outbox_row WHERE (outbox_row.organization_id,outbox_row.workspace_id,outbox_row.environment_id,outbox_row.id,outbox_row.topic,outbox_row.deterministic_key,outbox_row.payload_version)=(organization_value,workspace_value,environment_value,outbox_value,'runtime-events','runtime:'||batch_value,15))
  THEN IF batch_row.payload_schema_version='runtime-event-v2' OR batch_row.source_kind='otlp' AND batch_row.payload_schema_version='runtime-event-v1' THEN PERFORM zasp_runtime_precision_transport_ready();END IF; RETURN jsonb_build_object('batch_id',batch_row.batch_id,'generation',batch_row.batch_generation,'state',batch_row.state,'replayed',true);END IF;
  RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime batch conflict';
 END IF;
 IF (batch_row.raw_artifact_key,batch_row.content_digest,batch_row.payload_size_bytes) IS DISTINCT FROM (artifact_key_value,artifact_checksum_value,artifact_size_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime batch conflict';END IF;
 INSERT INTO zasp_runtime_batches(organization_id,workspace_id,environment_id,id,sensor_id,idempotency_key,payload_digest,event_count,payload_reference,payload_size_bytes,payload_media_type,payload_schema_version)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id,batch_row.sensor_id,batch_row.idempotency_key,batch_row.content_digest,batch_row.event_count,artifact_reference_value,batch_row.payload_size_bytes,batch_row.payload_media_type,batch_row.payload_schema_version);
 INSERT INTO zasp_discovery_jobs(organization_id,workspace_id,environment_id,id,kind,authority_id,idempotency_key,request_digest)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,job_value,'runtime',batch_row.batch_id,batch_row.idempotency_key,batch_row.request_digest);
 INSERT INTO zasp_runtime_stage_work(organization_id,workspace_id,environment_id,batch_id,batch_generation,stage,stage_order,implementation_version,input_digest)
 SELECT batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id,batch_row.batch_generation,stage_value.stage,stage_value.stage_order,CASE WHEN batch_row.payload_schema_version='runtime-event-v2' THEN CASE stage_value.stage WHEN 'archive' THEN 'runtime-archive-v2' WHEN 'index' THEN 'runtime-index-v2' WHEN 'correlate' THEN 'runtime-correlation-v4' WHEN 'project' THEN 'runtime-projection-v3' WHEN 'complete' THEN 'runtime-complete-v3' END WHEN batch_row.source_kind='otlp' AND batch_row.payload_schema_version='runtime-event-v1' THEN CASE stage_value.stage WHEN 'archive' THEN 'runtime-archive-v1' WHEN 'index' THEN 'runtime-index-v1' WHEN 'correlate' THEN 'runtime-correlation-v3' WHEN 'project' THEN 'runtime-projection-v2' WHEN 'complete' THEN 'runtime-complete-v2' END ELSE stage_value.version_value END,CASE WHEN stage_value.stage_order=1 THEN batch_row.content_digest ELSE NULL END
 FROM (VALUES('archive',1,'runtime-archive-v1'),('index',2,'runtime-index-v1'),('correlate',3,'runtime-correlation-v2'),('project',4,'runtime-projection-v1'),('complete',5,'runtime-complete-v1')) stage_value(stage,stage_order,version_value);
 event_payload:=jsonb_build_object('batch_id',batch_row.batch_id,'job_id',job_value,'generation',batch_row.batch_generation,'pipeline_version',15,'artifact_reference',artifact_reference_value,'artifact_key',artifact_key_value,'artifact_version_id',artifact_version_value,'artifact_checksum',encode(artifact_checksum_value,'hex'),'artifact_size_bytes',artifact_size_value,'payload_media_type',batch_row.payload_media_type,'payload_schema_version',batch_row.payload_schema_version,'event_count',batch_row.event_count,'request_digest',encode(batch_row.request_digest,'hex'));
 INSERT INTO zasp_discovery_outbox(organization_id,workspace_id,environment_id,id,topic,deterministic_key,payload_version,payload,payload_digest)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,outbox_value,'runtime-events','runtime:'||batch_row.batch_id,15,event_payload,digest(convert_to(event_payload::text,'UTF8'),'sha256'));
 UPDATE zasp_runtime_batch_authorities authority_row SET raw_artifact_reference=artifact_reference_value,raw_artifact_version_id=artifact_version_value,raw_artifact_checksum=artifact_checksum_value,raw_artifact_size_bytes=artifact_size_value,raw_artifact_kms_key=artifact_kms_key_value,state='queued',finalized_at=transaction_timestamp() WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id);
 result_value:=jsonb_build_object('batch_id',batch_row.batch_id,'generation',batch_row.batch_generation,'state','queued','replayed',false);
IF batch_row.payload_schema_version='runtime-event-v2' OR batch_row.source_kind='otlp' AND batch_row.payload_schema_version='runtime-event-v1' THEN PERFORM zasp_runtime_precision_transport_ready();END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_claim_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, receive_count_value integer, worker_value text, lease_token_value text, lease_seconds integer, visibility_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE batch_row zasp_runtime_batch_authorities%ROWTYPE;delivery_row zasp_runtime_deliveries%ROWTYPE;outbox_digest bytea;disposition_value text;replayed_value boolean:=false;lease_expires_value timestamptz;visibility_deadline_value timestamptz;
BEGIN
 PERFORM zasp_runtime_precision_transport_ready();
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(batch_value) OR generation_value<1 OR message_value !~ '^[A-Za-z0-9_-]{1,128}$' OR octet_length(message_digest_value)<>32 OR receive_count_value NOT BETWEEN 1 AND 100 OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR visibility_seconds<lease_seconds OR visibility_seconds>43200 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'zasp-runtime-delivery',organization_value,workspace_value,environment_value,batch_value),0));
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND OR batch_row.state='uploading' THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery missing';END IF;
 SELECT outbox.payload_digest INTO outbox_digest FROM zasp_discovery_outbox outbox WHERE (outbox.organization_id,outbox.workspace_id,outbox.environment_id,outbox.topic,outbox.deterministic_key,outbox.payload_version)=(organization_value,workspace_value,environment_value,'runtime-events','runtime:'||batch_value,15);
 IF NOT FOUND OR outbox_digest IS DISTINCT FROM message_digest_value THEN
  IF batch_row.state NOT IN('succeeded','failed','unknown','quarantined') THEN UPDATE zasp_runtime_batch_authorities authority_row SET state='quarantined',completed_at=transaction_timestamp(),completion_digest=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,message_value,encode(message_digest_value,'hex'),'delivery-drift'),'UTF8'),'sha256'),completion_result=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','malformed') WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value);END IF;
  PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','quarantined','replayed',false);
 END IF;
 SELECT * INTO delivery_row FROM zasp_runtime_deliveries existing WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value) FOR UPDATE;
 -- v36: exact durable outbox identity permits at-least-once publication.
 IF FOUND AND delivery_row.batch_generation=generation_value AND delivery_row.message_digest=message_digest_value AND delivery_row.message_id<>message_value THEN
  IF batch_row.state='unknown' OR delivery_row.disposition='unknown' THEN
   PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',true);
  END IF;
  IF batch_row.state IN('succeeded','failed','quarantined') THEN
   PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_terminal','replayed',true);
  END IF;
  IF delivery_row.disposition NOT IN('held','ack_pending') THEN
   PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',true);
  END IF;
  IF delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp() THEN
   PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_duplicate','replayed',true);
  END IF;
  UPDATE zasp_runtime_deliveries existing SET message_id=message_value,receive_count=receive_count_value,provider_ack_digest=NULL,lease_expires_at=transaction_timestamp()
   WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
  delivery_row.message_id:=message_value;delivery_row.receive_count:=receive_count_value;delivery_row.lease_expires_at:=transaction_timestamp();
 END IF;
 IF FOUND AND (delivery_row.batch_generation,delivery_row.message_id,delivery_row.message_digest) IS DISTINCT FROM (generation_value,message_value,message_digest_value) THEN
  UPDATE zasp_runtime_deliveries existing SET disposition='quarantined',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,visibility_deadline=NULL,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
  UPDATE zasp_runtime_batch_authorities authority_row SET state='quarantined',completed_at=transaction_timestamp(),completion_digest=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,message_value,encode(message_digest_value,'hex'),'delivery-drift'),'UTF8'),'sha256'),completion_result=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','malformed') WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value) AND authority_row.state NOT IN('succeeded','failed','unknown','quarantined');
  PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','quarantined','replayed',false);
 END IF;
 IF FOUND AND receive_count_value<delivery_row.receive_count THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime delivery conflict';END IF;
 IF FOUND AND delivery_row.disposition='acked' THEN PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_terminal','replayed',true);END IF;
 IF batch_row.state='unknown' OR FOUND AND delivery_row.disposition='unknown' THEN PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',FOUND);END IF;
 IF FOUND AND delivery_row.disposition IN('held','ack_pending') AND delivery_row.lease_expires_at>transaction_timestamp() AND (delivery_row.lease_owner,delivery_row.lease_token) IS DISTINCT FROM (worker_value,lease_token_value) THEN PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','busy','replayed',false,'lease_expires_at',delivery_row.lease_expires_at);END IF;
 IF EXISTS(SELECT 1 FROM zasp_runtime_deliveries other WHERE other.organization_id=organization_value AND other.batch_id<>batch_value AND other.disposition IN('held','ack_pending') AND other.lease_expires_at>transaction_timestamp()) THEN PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','busy','replayed',false);END IF;
 disposition_value:=CASE WHEN batch_row.state IN('succeeded','failed','quarantined') THEN 'ack_pending' ELSE 'held' END;
 lease_expires_value:=transaction_timestamp()+make_interval(secs=>lease_seconds);visibility_deadline_value:=transaction_timestamp()+make_interval(secs=>visibility_seconds);
 IF FOUND THEN
  replayed_value:=delivery_row.receive_count=receive_count_value AND delivery_row.disposition=disposition_value AND (delivery_row.lease_owner,delivery_row.lease_token) IS NOT DISTINCT FROM (worker_value,lease_token_value);
  UPDATE zasp_runtime_deliveries existing SET receive_count=GREATEST(existing.receive_count,receive_count_value),disposition=disposition_value,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=lease_expires_value,visibility_deadline=visibility_deadline_value,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 ELSE
  INSERT INTO zasp_runtime_deliveries(organization_id,workspace_id,environment_id,batch_id,batch_generation,message_id,message_digest,receive_count,disposition,lease_owner,lease_token,lease_expires_at,visibility_deadline) VALUES(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value,receive_count_value,disposition_value,worker_value,lease_token_value,lease_expires_value,visibility_deadline_value);
 END IF;
 PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition',CASE WHEN disposition_value='held' THEN 'claimed' ELSE disposition_value END,'replayed',replayed_value,'lease_expires_at',lease_expires_value,'visibility_deadline',visibility_deadline_value,'artifact_reference',batch_row.raw_artifact_reference,'artifact_key',batch_row.raw_artifact_key,'artifact_version_id',batch_row.raw_artifact_version_id,'artifact_checksum',encode(batch_row.raw_artifact_checksum,'hex'),'artifact_size_bytes',batch_row.raw_artifact_size_bytes,'artifact_kms_key',batch_row.raw_artifact_kms_key,'request_digest',encode(batch_row.request_digest,'hex'));
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_session_query_status(organization_value text, workspace_value text, environment_value text, principal_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE pending_value bigint;quarantined_value bigint;last_indexed_value timestamptz;oldest_pending_value timestamptz;
BEGIN
 IF NOT zasp_runtime_session_read_authorized(organization_value,workspace_value,environment_value,principal_value) THEN RETURN NULL;END IF;
 SELECT count(*),min(created_at) INTO pending_value,oldest_pending_value FROM (
  SELECT created_at FROM zasp_runtime_session_search_outbox WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND state IN('pending','leased') ORDER BY created_at LIMIT 1001
 ) pending;
 SELECT count(*) INTO quarantined_value FROM (
  SELECT created_at FROM zasp_runtime_session_search_outbox WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND state='quarantined' ORDER BY created_at LIMIT 1001
 ) quarantined;
 SELECT indexed_at INTO last_indexed_value FROM zasp_runtime_session_search_outbox WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND state='indexed' ORDER BY indexed_at DESC LIMIT 1;
 RETURN jsonb_build_object('state',CASE WHEN quarantined_value>0 THEN 'blocked' WHEN pending_value>0 THEN 'catching_up' WHEN last_indexed_value IS NULL THEN 'empty' ELSE 'current' END,
 'pending_batches',least(pending_value,1000),'pending_batches_capped',pending_value>1000,'quarantined_batches',least(quarantined_value,1000),'quarantined_batches_capped',quarantined_value>1000,
 'last_indexed_at',last_indexed_value,'oldest_pending_at',oldest_pending_value,'checked_at',statement_timestamp(),'selector_coverage','observed_only');
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_session_query_hydrate(organization_value text, workspace_value text, environment_value text, principal_value text, ids_value text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE status_value jsonb;items_value jsonb;actual_ids text[];
BEGIN
 IF ids_value IS NULL OR cardinality(ids_value)>101 OR array_ndims(ids_value)>1
 OR EXISTS(SELECT 1 FROM unnest(ids_value) id WHERE id IS NULL OR (id<>'unattributed' AND NOT zasp_valid_product_id(id)))
 OR ids_value IS DISTINCT FROM ARRAY(SELECT DISTINCT id FROM unnest(ids_value) id ORDER BY id) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session candidates rejected';
 END IF;
 status_value:=zasp_runtime_session_query_status(organization_value,workspace_value,environment_value,principal_value);
 IF status_value IS NULL THEN RETURN NULL;END IF;
 SELECT COALESCE(jsonb_agg(zasp_runtime_session_summary_json(summary_value) ORDER BY id),'[]'::jsonb),COALESCE(array_agg(id ORDER BY id),'{}'::text[])
 INTO items_value,actual_ids FROM zasp_runtime_session_summaries summary_value
 WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND id=ANY(ids_value);
 IF actual_ids IS DISTINCT FROM ids_value THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime session candidates unavailable';END IF;
 RETURN jsonb_build_object('items',items_value,'search',status_value);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_session_get(organization_value text, workspace_value text, environment_value text, principal_value text, id_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 IF NOT COALESCE(id_value='unattributed' OR zasp_valid_product_id(id_value),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session target rejected';END IF;
 IF NOT zasp_runtime_session_read_authorized(organization_value,workspace_value,environment_value,principal_value) THEN RETURN NULL;END IF;
 SELECT zasp_runtime_session_summary_json(summary_value) INTO result_value FROM zasp_runtime_session_summaries summary_value
 WHERE (organization_id,workspace_id,environment_id,id)=(organization_value,workspace_value,environment_value,id_value);
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_session_search_claim(worker_value text, token_value text, lease_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE work zasp_runtime_session_search_outbox%ROWTYPE;now_value timestamptz:=clock_timestamp();
BEGIN
 IF num_nulls(worker_value,token_value,lease_seconds)>0 OR worker_value !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$' OR token_value !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' OR lease_seconds NOT BETWEEN 5 AND 900
 OR NOT zasp_runtime_session_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime session search worker rejected';END IF;
 WITH exhausted AS (SELECT organization_id,workspace_id,environment_id,batch_id,batch_generation FROM zasp_runtime_session_search_outbox WHERE state IN('pending','leased') AND attempt>=100 AND (lease_until IS NULL OR lease_until<=now_value) FOR UPDATE SKIP LOCKED LIMIT 100)
 UPDATE zasp_runtime_session_search_outbox outbox_row SET state='quarantined',worker_id=NULL,lease_digest=NULL,lease_until=NULL FROM exhausted WHERE (outbox_row.organization_id,outbox_row.workspace_id,outbox_row.environment_id,outbox_row.batch_id,outbox_row.batch_generation)=(exhausted.organization_id,exhausted.workspace_id,exhausted.environment_id,exhausted.batch_id,exhausted.batch_generation);
 SELECT * INTO work FROM zasp_runtime_session_search_outbox WHERE attempt<100 AND ((state='pending' AND next_attempt_at<=now_value) OR (state='leased' AND lease_until<=now_value)) ORDER BY next_attempt_at,created_at,organization_id,workspace_id,environment_id,batch_id,batch_generation FOR UPDATE SKIP LOCKED LIMIT 1;
 IF NOT FOUND THEN RETURN NULL;END IF;
 now_value:=clock_timestamp();
 UPDATE zasp_runtime_session_search_outbox SET state='leased',attempt=attempt+1,worker_id=worker_value,lease_digest=digest(convert_to(token_value,'UTF8'),'sha256'),lease_until=now_value+make_interval(secs=>lease_seconds)
 WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation)=(work.organization_id,work.workspace_id,work.environment_id,work.batch_id,work.batch_generation) RETURNING * INTO work;
 RETURN jsonb_build_object('organization_id',work.organization_id,'workspace_id',work.workspace_id,'environment_id',work.environment_id,'batch_id',work.batch_id,'generation',work.batch_generation,'receipt_digest',encode(work.receipt_digest,'hex'),'receipt_reference',work.receipt_reference,'receipt_version',work.receipt_version,'document_ids',work.document_ids,'attempt',work.attempt,'lease_until',work.lease_until);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_session_search_heartbeat(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, token_value text, attempt_value integer, lease_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE work zasp_runtime_session_search_outbox%ROWTYPE;deadline timestamptz;now_value timestamptz;
BEGIN
 IF num_nulls(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,token_value,attempt_value,lease_seconds)>0 OR lease_seconds NOT BETWEEN 5 AND 900 OR NOT zasp_runtime_session_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime session search lease rejected';END IF;
 SELECT * INTO work FROM zasp_runtime_session_search_outbox WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime session search lease lost';END IF;
 now_value:=clock_timestamp();
 IF work.state<>'leased' OR work.lease_until<=now_value OR (work.worker_id,work.lease_digest,work.attempt) IS DISTINCT FROM (worker_value,digest(convert_to(token_value,'UTF8'),'sha256'),attempt_value) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime session search lease lost';END IF;
 UPDATE zasp_runtime_session_search_outbox SET lease_until=now_value+make_interval(secs=>lease_seconds) WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) RETURNING lease_until INTO deadline;
 RETURN jsonb_build_object('lease_until',deadline);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_session_search_finish(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, token_value text, attempt_value integer, receipt_digest_value bytea, outcome_value text, document_values text[], retry_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE work zasp_runtime_session_search_outbox%ROWTYPE;now_value timestamptz;
BEGIN
 IF num_nulls(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,token_value,attempt_value,receipt_digest_value,outcome_value,document_values,retry_seconds)>0 OR outcome_value NOT IN('indexed','retryable','quarantined') OR octet_length(receipt_digest_value)<>32
 OR (outcome_value='retryable' AND retry_seconds NOT BETWEEN 1 AND 3600) OR (outcome_value<>'retryable' AND retry_seconds<>0)
 OR NOT zasp_runtime_session_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime session search checkpoint rejected';END IF;
 SELECT * INTO work FROM zasp_runtime_session_search_outbox WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 now_value:=clock_timestamp();
 IF NOT FOUND OR (work.worker_id,work.lease_digest,work.attempt,work.receipt_digest) IS DISTINCT FROM (worker_value,digest(convert_to(token_value,'UTF8'),'sha256'),attempt_value,receipt_digest_value)
 OR (outcome_value='indexed' AND work.document_ids IS DISTINCT FROM document_values) OR (outcome_value<>'indexed' AND cardinality(document_values)<>0) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime session search checkpoint binding rejected';END IF;
 IF work.state='indexed' AND outcome_value='indexed' THEN
  RETURN jsonb_build_object('state','indexed','batch_id',work.batch_id,'generation',work.batch_generation,'attempt',work.attempt,'receipt_digest',encode(work.receipt_digest,'hex'),'indexed_at',work.indexed_at);
 END IF;
 IF work.state<>'leased' OR work.lease_until<=now_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime session search checkpoint lease lost';END IF;
 UPDATE zasp_runtime_session_search_outbox SET state=CASE WHEN outcome_value='retryable' THEN 'pending' ELSE outcome_value END,
 worker_id=CASE WHEN outcome_value='indexed' THEN worker_id ELSE NULL END,lease_digest=CASE WHEN outcome_value='indexed' THEN lease_digest ELSE NULL END,lease_until=NULL,
 indexed_at=CASE WHEN outcome_value='indexed' THEN now_value ELSE NULL END,next_attempt_at=now_value+make_interval(secs=>retry_seconds)
 WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) RETURNING * INTO work;
 RETURN jsonb_build_object('state',work.state,'batch_id',work.batch_id,'generation',work.batch_generation,'attempt',work.attempt,'receipt_digest',encode(work.receipt_digest,'hex'),'indexed_at',work.indexed_at);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_enqueue_approval_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE webhook_count integer;webhook_body jsonb;configuration_value jsonb;delivery_value text;payload_value jsonb;destination_value text;destination_host text;
BEGIN
 IF NEW.state<>'pending' THEN RETURN NEW;END IF;
 SELECT count(*),(jsonb_agg(record_value.body ORDER BY record_value.id)->0) INTO webhook_count,webhook_body
   FROM zasp_workflow_records record_value
  WHERE (record_value.organization_id,record_value.workspace_id,record_value.environment_id,record_value.kind)=(NEW.organization_id,NEW.workspace_id,NEW.environment_id,'integration')
    AND record_value.deleted_at IS NULL AND record_value.body->>'connector_key'='generic-webhook' AND record_value.body->>'status'='configured';
 IF webhook_count<>1 OR jsonb_typeof(webhook_body->'configuration')<>'object' OR (webhook_body->'configuration')-ARRAY['destination_url','signing_secret_reference']<>'{}'::jsonb THEN RETURN NEW;END IF;
 configuration_value:=webhook_body->'configuration';
 destination_value:=configuration_value->>'destination_url';
 destination_host:=split_part(split_part(substr(destination_value,9),'/',1),':',1);
 IF destination_value IS NULL OR char_length(destination_value) NOT BETWEEN 12 AND 2048 OR destination_value!~'^https://[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?(:443)?/[^?#]*$' OR destination_host='' OR destination_host='localhost' OR destination_host LIKE '%.localhost' OR destination_host LIKE '%.local' OR destination_host LIKE '%..%' OR destination_host~'^[0-9.]+$' OR configuration_value->>'signing_secret_reference'!~'^secret_ref_[A-Za-z0-9][A-Za-z0-9._/-]{0,115}$' THEN RETURN NEW;END IF;
 delivery_value:=zasp_discovery_canonical_id(NEW.organization_id,NEW.workspace_id,NEW.environment_id,'security_agent_approval_notification',NEW.approval_id);
 payload_value:=jsonb_build_object('approval',jsonb_build_object('id',NEW.approval_id,'run_id',NEW.run_id),'delivery_id',delivery_value,'event','security_agent.approval_required','scope',jsonb_build_object('environment_id',NEW.environment_id,'organization_id',NEW.organization_id,'workspace_id',NEW.workspace_id),'version',1);
 INSERT INTO zasp_security_agent_approval_notifications(organization_id,workspace_id,environment_id,delivery_id,approval_id,run_id,payload,payload_digest,destination_url,secret_reference)
 VALUES(NEW.organization_id,NEW.workspace_id,NEW.environment_id,delivery_value,NEW.approval_id,NEW.run_id,payload_value,digest(convert_to(payload_value::text,'UTF8'),'sha256'),destination_value,configuration_value->>'signing_secret_reference')
 ON CONFLICT(organization_id,workspace_id,environment_id,approval_id) DO NOTHING;
 RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_claim_approval_notification(owner_value text, lease_token_value text, lease_seconds_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE notification zasp_security_agent_approval_notifications%ROWTYPE;
BEGIN
 IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR owner_value IS NULL OR char_length(owner_value) NOT BETWEEN 3 AND 128 OR owner_value<>btrim(owner_value) OR owner_value~E'[\\x00\\r\\n]' OR lease_token_value!~'^[0-9a-f]{64}$' OR lease_seconds_value NOT BETWEEN 15 AND 60 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='approval notification claim rejected';END IF;
 UPDATE zasp_security_agent_approval_notifications SET state='exhausted',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=transaction_timestamp() WHERE state='leased' AND lease_expires_at<=transaction_timestamp() AND attempt>=10;
 SELECT * INTO notification FROM zasp_security_agent_approval_notifications row_value
  WHERE (row_value.state IN('pending','retryable') AND row_value.available_at<=transaction_timestamp()) OR (row_value.state='leased' AND row_value.lease_expires_at<=transaction_timestamp() AND row_value.attempt<10)
  ORDER BY row_value.available_at,row_value.created_at,row_value.delivery_id FOR UPDATE SKIP LOCKED LIMIT 1;
 IF NOT FOUND THEN RETURN jsonb_build_object('found',false);END IF;
 UPDATE zasp_security_agent_approval_notifications SET state='leased',attempt=attempt+1,lease_owner=owner_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds_value),updated_at=transaction_timestamp()
  WHERE (organization_id,workspace_id,environment_id,delivery_id)=(notification.organization_id,notification.workspace_id,notification.environment_id,notification.delivery_id) RETURNING * INTO notification;
 RETURN jsonb_build_object('found',true,'organization_id',notification.organization_id,'workspace_id',notification.workspace_id,'environment_id',notification.environment_id,'delivery_id',notification.delivery_id,'approval_id',notification.approval_id,'run_id',notification.run_id,'payload',notification.payload::text,'payload_digest','sha256:'||encode(notification.payload_digest,'hex'),'destination_url',notification.destination_url,'secret_reference',notification.secret_reference,'lease_token',notification.lease_token,'lease_expires_at',notification.lease_expires_at,'attempt',notification.attempt);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_complete_approval_notification(organization_value text, workspace_value text, environment_value text, delivery_value text, lease_token_value text, payload_digest_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE changed integer;
BEGIN
 IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(delivery_value) OR lease_token_value!~'^[0-9a-f]{64}$' OR payload_digest_value!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='approval notification completion rejected';END IF;
 UPDATE zasp_security_agent_approval_notifications SET state='delivered',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,completed_at=transaction_timestamp(),updated_at=transaction_timestamp()
  WHERE (organization_id,workspace_id,environment_id,delivery_id,state,lease_token,payload_digest)=(organization_value,workspace_value,environment_value,delivery_value,'leased',lease_token_value,decode(substr(payload_digest_value,8),'hex')) AND lease_expires_at>transaction_timestamp();
 GET DIAGNOSTICS changed=ROW_COUNT;
 IF changed<>1 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='approval notification lease lost';END IF;
 RETURN jsonb_build_object('transition','delivered');
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_fail_approval_notification(organization_value text, workspace_value text, environment_value text, delivery_value text, lease_token_value text, payload_digest_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE notification zasp_security_agent_approval_notifications%ROWTYPE;
BEGIN
 IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(delivery_value) OR lease_token_value!~'^[0-9a-f]{64}$' OR payload_digest_value!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='approval notification failure rejected';END IF;
 SELECT * INTO notification FROM zasp_security_agent_approval_notifications row_value WHERE (row_value.organization_id,row_value.workspace_id,row_value.environment_id,row_value.delivery_id)=(organization_value,workspace_value,environment_value,delivery_value) FOR UPDATE;
 IF NOT FOUND OR notification.state<>'leased' OR notification.lease_token<>lease_token_value OR notification.lease_expires_at<=transaction_timestamp() OR notification.payload_digest<>decode(substr(payload_digest_value,8),'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='approval notification lease lost';END IF;
 IF notification.attempt>=10 THEN
  UPDATE zasp_security_agent_approval_notifications SET state='exhausted',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,delivery_id)=(organization_value,workspace_value,environment_value,delivery_value);
  RETURN jsonb_build_object('transition','exhausted');
 END IF;
 UPDATE zasp_security_agent_approval_notifications SET state='retryable',available_at=transaction_timestamp()+make_interval(secs=>LEAST(60,attempt*attempt)),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,delivery_id)=(organization_value,workspace_value,environment_value,delivery_value);
 RETURN jsonb_build_object('transition','retryable');
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_execution_integration_setup_status(organization_value text, workspace_value text, environment_value text, integration_value text, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE integration_row zasp_integrations%ROWTYPE;connection_row zasp_integration_connections%ROWTYPE;subject_row zasp_discovery_connection_subjects%ROWTYPE;credential_row zasp_connector_credentials%ROWTYPE;authorization_state text:='pending';scope_kind_value text:='none';scope_label_value text;repository_selection_value text;permissions_value jsonb:='[]'::jsonb;sensor_count_value integer:=0;healthy_count_value integer:=0;missing_count_value integer:=0;unsupported_count_value integer:=0;coverage_state text:='not_applicable';coverage_reason text:='not_applicable';updated_value timestamptz;
BEGIN
  IF NOT zasp_production_integration_setup_readiness(expected_checksum,expected_fingerprint) OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(integration_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration setup status rejected';END IF;
  SELECT * INTO integration_row FROM zasp_integrations integration WHERE (integration.organization_id,integration.workspace_id,integration.environment_id,integration.id)=(organization_value,workspace_value,environment_value,integration_value) AND integration.kind IN('aws','kubernetes','github','okta') AND integration.state<>'deleted';
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration setup status missing';END IF;
  updated_value:=integration_row.updated_at;
  IF (SELECT count(*) FROM zasp_integration_connections connection WHERE (connection.organization_id,connection.workspace_id,connection.environment_id,connection.integration_id,connection.provider,connection.state)=(organization_value,workspace_value,environment_value,integration_value,integration_row.kind,'verified'))=1 THEN
    SELECT * INTO STRICT connection_row FROM zasp_integration_connections connection WHERE (connection.organization_id,connection.workspace_id,connection.environment_id,connection.integration_id,connection.provider,connection.state)=(organization_value,workspace_value,environment_value,integration_value,integration_row.kind,'verified');
    SELECT * INTO subject_row FROM zasp_discovery_connection_subjects subject WHERE (subject.organization_id,subject.workspace_id,subject.environment_id,subject.integration_id,subject.connection_id,subject.provider,subject.connection_version,subject.configuration_digest)=(organization_value,workspace_value,environment_value,integration_value,connection_row.id,integration_row.kind,connection_row.version,digest(convert_to(integration_row.configuration::text,'UTF8'),'sha256'));
    IF FOUND THEN
      updated_value:=greatest(updated_value,connection_row.updated_at,subject_row.verified_at);
      IF integration_row.kind IN('aws','kubernetes') THEN
        authorization_state:='verified';scope_kind_value:=subject_row.subject_kind;scope_label_value:=subject_row.subject_id;
      ELSIF (SELECT count(*) FROM zasp_connector_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.integration_id,credential.provider,credential.status,credential.credential_reference)=(organization_value,workspace_value,environment_value,integration_value,integration_row.kind,'active',connection_row.connection_reference))=1 THEN
        SELECT * INTO STRICT credential_row FROM zasp_connector_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.integration_id,credential.provider,credential.status,credential.credential_reference)=(organization_value,workspace_value,environment_value,integration_value,integration_row.kind,'active',connection_row.connection_reference);
        updated_value:=greatest(updated_value,credential_row.updated_at);
        IF integration_row.kind='github' AND subject_row.subject_kind='github_installation' AND credential_row.metadata->>'installation_id'=subject_row.subject_id AND credential_row.metadata->>'account_type'='Organization' AND credential_row.metadata->>'account_login'~'^[A-Za-z0-9]([A-Za-z0-9-]{0,37}[A-Za-z0-9])?$' AND credential_row.metadata->>'repository_selection' IN('all','selected') AND credential_row.metadata->'permissions'='{"actions":"read","contents":"read","metadata":"read"}'::jsonb THEN
          authorization_state:='verified';scope_kind_value:='github_organization';scope_label_value:=credential_row.metadata->>'account_login';repository_selection_value:=credential_row.metadata->>'repository_selection';permissions_value:='["actions:read","contents:read","metadata:read"]'::jsonb;
        ELSIF integration_row.kind='okta' AND subject_row.subject_kind='okta_tenant' AND credential_row.metadata->>'tenant'=subject_row.subject_id AND credential_row.metadata->'scopes'='["offline_access","okta.apps.read","okta.groups.read","okta.users.read"]'::jsonb THEN
          authorization_state:='verified';scope_kind_value:='okta_tenant';scope_label_value:=subject_row.subject_id;permissions_value:=credential_row.metadata->'scopes';
        ELSE authorization_state:='degraded';END IF;
      ELSE authorization_state:='degraded';END IF;
    END IF;
  END IF;
  IF integration_row.kind='kubernetes' THEN
    SELECT count(*),count(*) FILTER(WHERE sensor.state='active' AND heartbeat.status='healthy' AND heartbeat.observed_at>=transaction_timestamp()-interval '5 minutes' AND COALESCE((heartbeat.metadata->>'btf')::boolean,false)),count(*) FILTER(WHERE heartbeat.sensor_id IS NULL OR heartbeat.observed_at<transaction_timestamp()-interval '5 minutes'),count(*) FILTER(WHERE heartbeat.observed_at>=transaction_timestamp()-interval '5 minutes' AND NOT COALESCE((heartbeat.metadata->>'btf')::boolean,false)),greatest(updated_value,COALESCE(max(sensor.updated_at),updated_value),COALESCE(max(heartbeat.observed_at),updated_value)) INTO sensor_count_value,healthy_count_value,missing_count_value,unsupported_count_value,updated_value
    FROM zasp_sensors sensor LEFT JOIN zasp_sensor_heartbeats heartbeat ON (heartbeat.organization_id,heartbeat.workspace_id,heartbeat.environment_id,heartbeat.sensor_id)=(sensor.organization_id,sensor.workspace_id,sensor.environment_id,sensor.id)
    WHERE (sensor.organization_id,sensor.workspace_id,sensor.environment_id,sensor.kind)=(organization_value,workspace_value,environment_value,'tetragon') AND sensor.state NOT IN('revoked','deleted');
    IF sensor_count_value=0 THEN coverage_state:='not_enrolled';coverage_reason:='not_enrolled';
    ELSIF missing_count_value>0 THEN coverage_state:='awaiting_heartbeat';coverage_reason:='missing_gateway';
    ELSIF unsupported_count_value>0 THEN coverage_state:='degraded';coverage_reason:='unsupported_kernel';
    ELSIF healthy_count_value=sensor_count_value THEN coverage_state:='healthy';coverage_reason:='verified';
    ELSE coverage_state:='degraded';coverage_reason:='degraded';END IF;
  END IF;
  RETURN jsonb_build_object('integration_id',integration_value,'connector_key',integration_row.kind,'authorization',jsonb_build_object('state',authorization_state,'scope_kind',scope_kind_value,'scope_label',scope_label_value,'repository_selection',repository_selection_value,'permissions',permissions_value),'runtime_coverage',jsonb_build_object('state',coverage_state,'reason',coverage_reason,'sensor_count',sensor_count_value,'healthy_sensor_count',healthy_count_value),'updated_at',to_char(updated_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_integration_webhook_test_reserve(organization_value text, workspace_value text, environment_value text, principal_value text, integration_value text, expected_version bigint, key_value text, audit_value text, correlation_value text, delivery_value text, token_value text, lease_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item zasp_integration_webhook_tests%ROWTYPE;workflow zasp_workflow_records%ROWTYPE;request_digest_value bytea;payload_value text;destination_value text;secret_value text;
BEGIN
 IF NOT COALESCE(zasp_production_integration_webhook_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=35),(SELECT value FROM zasp_schema_metadata WHERE key='production_integration_webhook_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='integration webhook unavailable';END IF;
 IF NOT COALESCE(zasp_valid_product_id(organization_value) AND zasp_valid_product_id(workspace_value) AND zasp_valid_product_id(environment_value) AND zasp_valid_product_id(principal_value) AND zasp_valid_product_id(integration_value) AND zasp_valid_product_id(audit_value) AND zasp_valid_product_id(correlation_value) AND audit_value<>correlation_value AND zasp_valid_product_id(delivery_value) AND expected_version BETWEEN 1 AND 1000000 AND key_value ~ '^[A-Za-z0-9._:-]{16,128}$' AND token_value ~ '^[0-9a-f]{64}$' AND lease_seconds BETWEEN 5 AND 30,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration webhook rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'integration-webhook',organization_value,workspace_value,environment_value,principal_value,key_value),0));
 request_digest_value:=digest(convert_to(jsonb_build_object('integration_id',integration_value,'expected_version',expected_version)::text,'UTF8'),'sha256');
 SELECT * INTO item FROM zasp_integration_webhook_tests WHERE (organization_id,workspace_id,environment_id,principal_id,idempotency_key)=(organization_value,workspace_value,environment_value,principal_value,key_value) FOR UPDATE;
 IF FOUND THEN
  IF item.request_digest<>request_digest_value THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='integration webhook conflict';END IF;
  IF item.state IN('succeeded','failed') THEN RETURN jsonb_build_object('state',item.state,'delivery_id',item.delivery_id,'status',zasp_integration_webhook_test_public(item));END IF;
  IF item.lease_expires_at>transaction_timestamp() THEN RETURN jsonb_build_object('state','busy','delivery_id',item.delivery_id,'lease_expires_at',to_char(item.lease_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));END IF;
 END IF;
 SELECT * INTO workflow FROM zasp_workflow_records WHERE (organization_id,workspace_id,environment_id,kind,id)=(organization_value,workspace_value,environment_value,'integration',integration_value) AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration webhook missing';END IF;
 IF workflow.version<>expected_version OR workflow.body->>'connector_key' IS DISTINCT FROM 'generic-webhook' OR workflow.body->>'status' IS DISTINCT FROM 'configured' THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='integration webhook configuration changed';END IF;
 destination_value:=workflow.body->'configuration'->>'destination_url';secret_value:=workflow.body->'configuration'->>'signing_secret_reference';
 IF jsonb_typeof(workflow.body->'configuration') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration webhook configuration rejected';END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(workflow.body->'configuration'))<>2 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration webhook configuration rejected';END IF;
 IF NOT COALESCE(length(destination_value)<=2048 AND destination_value ~ '^https://[a-z0-9][a-z0-9.-]*[a-z0-9](:443)?(/[^?#[:cntrl:] ]*)?$' AND position('..' IN destination_value)=0 AND secret_value ~ '^secret_ref_[A-Za-z0-9][A-Za-z0-9._/-]{0,115}$' AND position('..' IN secret_value)=0 AND position('//' IN secret_value)=0,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration webhook configuration rejected';END IF;
 IF item.delivery_id IS NOT NULL THEN
  IF item.configuration_digest<>digest(convert_to((workflow.body->'configuration')::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='integration webhook configuration changed';END IF;
  IF item.attempt=3 THEN
   UPDATE zasp_integration_webhook_tests SET state='failed',completed_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,delivery_id)=(organization_value,workspace_value,environment_value,item.delivery_id) RETURNING * INTO item;
   RETURN jsonb_build_object('state','failed','delivery_id',item.delivery_id,'status',zasp_integration_webhook_test_public(item));
  END IF;
  UPDATE zasp_integration_webhook_tests SET lease_token=token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),attempt=attempt+1 WHERE (organization_id,workspace_id,environment_id,delivery_id)=(organization_value,workspace_value,environment_value,item.delivery_id) RETURNING * INTO item;
 ELSE
  IF EXISTS(SELECT 1 FROM zasp_integration_webhook_tests WHERE (organization_id,workspace_id,environment_id,integration_id)=(organization_value,workspace_value,environment_value,integration_value) AND attempted_at>transaction_timestamp()-interval '10 seconds') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='integration webhook test busy';END IF;
  payload_value:=jsonb_build_object('delivery_id',delivery_value,'event','integration.webhook.test','integration',jsonb_build_object('id',integration_value,'version',expected_version),'scope',jsonb_build_object('organization_id',organization_value,'workspace_id',workspace_value,'environment_id',environment_value),'sent_at',to_char(transaction_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'version',1)::text;
  INSERT INTO zasp_integration_webhook_tests(organization_id,workspace_id,environment_id,integration_id,principal_id,idempotency_key,delivery_id,integration_version,request_digest,configuration_digest,destination_url,secret_reference,payload,payload_digest,state,lease_token,lease_expires_at,attempt,audit_id,correlation_id)
  VALUES(organization_value,workspace_value,environment_value,integration_value,principal_value,key_value,delivery_value,expected_version,request_digest_value,digest(convert_to((workflow.body->'configuration')::text,'UTF8'),'sha256'),destination_value,secret_value,payload_value,'sha256:'||encode(digest(convert_to(payload_value,'UTF8'),'sha256'),'hex'),'leased',token_value,transaction_timestamp()+make_interval(secs=>lease_seconds),1,audit_value,correlation_value) RETURNING * INTO item;
  INSERT INTO zasp_workflow_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,principal_id,operation,resource_kind,resource_id,resource_version) VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,principal_value,'testIntegrationWebhook','integration',integration_value,expected_version);
 END IF;
 RETURN jsonb_build_object('state','dispatch','delivery_id',item.delivery_id,'payload',item.payload,'payload_digest',item.payload_digest,'destination_url',item.destination_url,'secret_reference',item.secret_reference,'lease_expires_at',to_char(item.lease_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_integration_webhook_test_complete(organization_value text, workspace_value text, environment_value text, delivery_value text, token_value text, digest_value text, succeeded_value boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item zasp_integration_webhook_tests%ROWTYPE;next_state text:=CASE WHEN succeeded_value THEN 'succeeded' ELSE 'failed' END;
BEGIN
 IF NOT COALESCE(zasp_production_integration_webhook_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=35),(SELECT value FROM zasp_schema_metadata WHERE key='production_integration_webhook_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='integration webhook unavailable';END IF;
 SELECT * INTO item FROM zasp_integration_webhook_tests WHERE (organization_id,workspace_id,environment_id,delivery_id,lease_token,payload_digest)=(organization_value,workspace_value,environment_value,delivery_value,token_value,digest_value) FOR UPDATE;
 IF NOT FOUND OR succeeded_value IS NULL OR item.state<>next_state AND (item.state<>'leased' OR item.lease_expires_at<=transaction_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='integration webhook completion rejected';END IF;
 IF item.state='leased' THEN UPDATE zasp_integration_webhook_tests SET state=next_state,completed_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,delivery_id)=(organization_value,workspace_value,environment_value,delivery_value) RETURNING * INTO item;END IF;
 RETURN zasp_integration_webhook_test_public(item);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_integration_webhook_test_status(organization_value text, workspace_value text, environment_value text, integration_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item zasp_integration_webhook_tests%ROWTYPE;
BEGIN
 IF NOT COALESCE(zasp_production_integration_webhook_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=35),(SELECT value FROM zasp_schema_metadata WHERE key='production_integration_webhook_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='integration webhook unavailable';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_workflow_records WHERE (organization_id,workspace_id,environment_id,kind,id)=(organization_value,workspace_value,environment_value,'integration',integration_value) AND deleted_at IS NULL AND body->>'connector_key'='generic-webhook') THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration webhook missing';END IF;
 SELECT tests.* INTO item FROM zasp_integration_webhook_tests tests JOIN zasp_workflow_records workflow ON (workflow.organization_id,workflow.workspace_id,workflow.environment_id,workflow.kind,workflow.id,workflow.version)=(tests.organization_id,tests.workspace_id,tests.environment_id,'integration',tests.integration_id,tests.integration_version) WHERE (tests.organization_id,tests.workspace_id,tests.environment_id,tests.integration_id)=(organization_value,workspace_value,environment_value,integration_value) AND tests.configuration_digest=digest(convert_to((workflow.body->'configuration')::text,'UTF8'),'sha256') ORDER BY tests.attempted_at DESC,tests.delivery_id LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration webhook test missing';END IF;
 RETURN zasp_integration_webhook_test_public(item);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_connector_claim_reconciliation(owner_value text, lease_seconds integer, limit_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb; available_slots integer;
BEGIN
  IF length(owner_value) NOT BETWEEN 3 AND 128 OR lease_seconds NOT BETWEEN 5 AND 300 OR limit_value NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid reconciliation claim'; END IF;
	PERFORM pg_advisory_xact_lock(742516322);
	SELECT GREATEST(0,LEAST(limit_value,100-count(*)::integer)) INTO available_slots FROM zasp_connector_effects WHERE status='unknown' AND lease_expires_at>transaction_timestamp();
	IF available_slots=0 THEN RETURN jsonb_build_object('items','[]'::jsonb); END IF;
  WITH eligible_lanes AS MATERIALIZED (SELECT lane.* FROM zasp_connector_effect_lane_scopes lane WHERE NOT EXISTS(SELECT 1 FROM zasp_connector_effects live WHERE live.provider=lane.provider AND live.operation=lane.operation AND live.status='unknown' AND live.lease_expires_at>transaction_timestamp())), candidates AS (SELECT lane.provider,lane.operation,effect.organization_id,effect.workspace_id,effect.environment_id,effect.id,effect.updated_at FROM eligible_lanes lane CROSS JOIN LATERAL (SELECT candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.id,candidate.updated_at FROM zasp_connector_effects candidate WHERE candidate.provider=lane.provider AND candidate.operation=lane.operation AND candidate.organization_id=lane.organization_id AND candidate.workspace_id=lane.workspace_id AND candidate.environment_id=lane.environment_id AND candidate.status='unknown' AND candidate.attempt<100 AND candidate.available_at<=transaction_timestamp() AND candidate.updated_at<=transaction_timestamp()-interval '15 seconds' AND (candidate.lease_expires_at IS NULL OR candidate.lease_expires_at<=transaction_timestamp()) AND (candidate.operation<>'pkce_cleanup' OR candidate.oauth_attempt_id IS NULL OR NOT EXISTS(SELECT 1 FROM zasp_connector_oauth_attempts attempt WHERE (attempt.organization_id,attempt.workspace_id,attempt.environment_id,attempt.id)=(candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.oauth_attempt_id) AND attempt.status='consuming')) ORDER BY candidate.updated_at,candidate.id LIMIT 1) effect),
  lane_fair AS (SELECT candidates.*,row_number() OVER(PARTITION BY provider,operation ORDER BY updated_at,id) lane_rank FROM candidates),
  fair AS (SELECT lane_fair.*,row_number() OVER(PARTITION BY organization_id,workspace_id,environment_id ORDER BY updated_at,id) organization_rank FROM lane_fair WHERE lane_rank=1),
  selected AS (SELECT effect.organization_id,effect.workspace_id,effect.environment_id,effect.id FROM zasp_connector_effects effect JOIN fair ON (fair.organization_id,fair.workspace_id,fair.environment_id,fair.id)=(effect.organization_id,effect.workspace_id,effect.environment_id,effect.id) ORDER BY fair.organization_rank,effect.updated_at,effect.id FOR UPDATE OF effect SKIP LOCKED LIMIT available_slots),
  updated AS (UPDATE zasp_connector_effects effect SET attempt=effect.attempt+1,lease_owner=owner_value,lease_token=encode(gen_random_bytes(32),'hex'),lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),updated_at=transaction_timestamp() FROM selected WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.id)=(selected.organization_id,selected.workspace_id,selected.environment_id,selected.id) RETURNING effect.*)
	  SELECT jsonb_build_object('items',COALESCE(jsonb_agg(jsonb_build_object('organization_id',organization_id,'workspace_id',workspace_id,'environment_id',environment_id,'id',id,'integration_id',integration_id,'oauth_attempt_id',oauth_attempt_id,'principal_id',(SELECT principal_id FROM zasp_connector_oauth_attempts attempt WHERE (attempt.organization_id,attempt.workspace_id,attempt.environment_id,attempt.id)=(updated.organization_id,updated.workspace_id,updated.environment_id,updated.oauth_attempt_id)),'requested_scopes',(SELECT requested_scopes FROM zasp_connector_oauth_attempts attempt WHERE (attempt.organization_id,attempt.workspace_id,attempt.environment_id,attempt.id)=(updated.organization_id,updated.workspace_id,updated.environment_id,updated.oauth_attempt_id)),'provider',provider,'operation',operation,'connection_reference',connection_reference,'idempotency_key',idempotency_key,'request_digest',encode(request_digest,'hex'),'last_error_code',last_error_code,'attempt',attempt,'lease_owner',lease_owner,'lease_token',lease_token,'lease_expires_at',lease_expires_at) ORDER BY updated_at,id),'[]'::jsonb)) INTO result_value FROM updated;
  RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_red_team_finish_run_v38(organization_value text, workspace_value text, environment_value text, run_value text, worker_value text, token_value bytea, input_digest_value bytea, verdict_value text, objective_value text, behavior_value text, error_value text, evidence_value jsonb, reference_value text, key_value text, version_value text, checksum_value bytea, size_value bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row zasp_red_team_runs%ROWTYPE;
BEGIN IF NOT zasp_red_team_principal_ready('zasp_red_team_worker') OR octet_length(input_digest_value)<>32 OR verdict_value NOT IN('pass','fail','engine_error') OR verdict_value IN('pass','fail') AND error_value IS NOT NULL OR verdict_value='engine_error' AND error_value NOT IN('denied','malformed','outcome_unknown','exhausted') OR length(objective_value) NOT BETWEEN 1 AND 512 OR objective_value<>btrim(objective_value) OR objective_value~'[[:cntrl:]]' OR length(behavior_value) NOT BETWEEN 1 AND 2048 OR behavior_value<>btrim(behavior_value) OR behavior_value~'[[:cntrl:]]' OR jsonb_typeof(evidence_value)<>'array' OR jsonb_array_length(evidence_value)>64 OR EXISTS(SELECT 1 FROM jsonb_array_elements(evidence_value) evidence_item WHERE jsonb_typeof(evidence_item)<>'string' OR length(evidence_item#>>'{}') NOT BETWEEN 1 AND 512 OR evidence_item#>>'{}'<>btrim(evidence_item#>>'{}') OR evidence_item#>>'{}'~'[[:cntrl:]]') OR reference_value!~'^s3://[a-z0-9][a-z0-9.-]{2,62}/organizations/' OR length(key_value) NOT BETWEEN 1 AND 1024 OR substring(reference_value FROM '^s3://[a-z0-9][a-z0-9.-]{2,62}/(.+)$') IS DISTINCT FROM key_value OR key_value IS DISTINCT FROM 'organizations/'||organization_value||'/workspaces/'||workspace_value||'/environments/'||environment_value||'/artifacts/'||run_value OR length(version_value) NOT BETWEEN 1 AND 512 OR version_value~'[[:space:][:cntrl:]]' OR octet_length(checksum_value)<>32 OR size_value NOT BETWEEN 1 AND 67108864 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='red team run completion rejected';END IF;
 SELECT * INTO STRICT run_row FROM zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id,state,worker_id,lease_token,input_digest)=(organization_value,workspace_value,environment_value,run_value,'leased',worker_value,token_value,input_digest_value) AND lease_expires_at>transaction_timestamp() FOR UPDATE;
 IF run_row.cancel_requested THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='red team run cancellation wins';END IF;
 INSERT INTO zasp_red_team_attempts(organization_id,workspace_id,environment_id,run_id,attempt,input_digest,verdict,objective,behavior,error_code,evidence,evidence_reference,evidence_key,evidence_version_id,evidence_checksum,evidence_size) VALUES(organization_value,workspace_value,environment_value,run_value,run_row.attempt,input_digest_value,verdict_value,objective_value,behavior_value,error_value,evidence_value,reference_value,key_value,version_value,checksum_value,size_value) ON CONFLICT(organization_id,workspace_id,environment_id,run_id,attempt) DO NOTHING;
 IF NOT FOUND AND NOT EXISTS(SELECT 1 FROM zasp_red_team_attempts attempt_value WHERE (attempt_value.organization_id,attempt_value.workspace_id,attempt_value.environment_id,attempt_value.run_id,attempt_value.attempt,attempt_value.input_digest,attempt_value.verdict,attempt_value.objective,attempt_value.behavior,attempt_value.error_code,attempt_value.evidence,attempt_value.evidence_reference,attempt_value.evidence_key,attempt_value.evidence_version_id,attempt_value.evidence_checksum,attempt_value.evidence_size) IS NOT DISTINCT FROM (organization_value,workspace_value,environment_value,run_value,run_row.attempt,input_digest_value,verdict_value,objective_value,behavior_value,error_value,evidence_value,reference_value,key_value,version_value,checksum_value,size_value)) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='red team attempt conflict';END IF;
 UPDATE zasp_red_team_runs SET version=version+1,state='complete',verdict=verdict_value,error_code=error_value,evidence_reference=reference_value,evidence_key=key_value,evidence_version_id=version_value,evidence_checksum=checksum_value,evidence_size=size_value,completed_at=transaction_timestamp(),worker_id=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value) RETURNING * INTO run_row;RETURN zasp_red_team_run_json(run_row);
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='red team run lease rejected';END
$function$

CREATE OR REPLACE FUNCTION public.zasp_red_team_valid_input_artifact(organization_value text, workspace_value text, environment_value text, input_value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE reference_value text; key_value text; prefix_value text;
BEGIN
 IF input_value IS NULL OR jsonb_typeof(input_value)<>'object' THEN RETURN false;END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(input_value))<>4 OR NOT input_value ?& ARRAY['reference','version_id','sha256','size_bytes']
 OR jsonb_typeof(input_value->'reference')<>'string' OR jsonb_typeof(input_value->'version_id')<>'string' OR jsonb_typeof(input_value->'sha256')<>'string' OR jsonb_typeof(input_value->'size_bytes')<>'number'
 OR input_value->>'sha256' !~ '^[a-f0-9]{64}$' OR input_value->>'sha256'=repeat('0',64)
 OR length(input_value->>'version_id') NOT BETWEEN 1 AND 512 OR input_value->>'version_id' ~ '[[:space:][:cntrl:]]'
 OR input_value->>'size_bytes' !~ '^[1-9][0-9]{0,4}$' THEN RETURN false;END IF;
 IF (input_value->>'size_bytes')::bigint>65536 THEN RETURN false;END IF;
 reference_value:=input_value->>'reference';
 IF NOT zasp_discovery_s3_object_reference(reference_value) THEN RETURN false;END IF;
 key_value:=substring(reference_value FROM '^s3://[^/]+/(.+)$');
 prefix_value:='organizations/'||organization_value||'/workspaces/'||workspace_value||'/environments/'||environment_value||'/artifacts/';
 RETURN COALESCE(zasp_valid_product_id(organization_value) AND zasp_valid_product_id(workspace_value) AND zasp_valid_product_id(environment_value) AND left(key_value,length(prefix_value))=prefix_value AND zasp_valid_product_id(substring(key_value FROM length(prefix_value)+1)),false);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_red_team_finish_run(organization_value text, workspace_value text, environment_value text, run_value text, worker_value text, token_value bytea, input_digest_value bytea, verdict_value text, objective_value text, behavior_value text, error_value text, evidence_value jsonb, reference_value text, key_value text, version_value text, checksum_value bytea, size_value bigint, input_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN PERFORM public.zasp_production_security_agent_existing_tests_legacy_run(organization_value,workspace_value,environment_value,run_value,'zasp_red_team_worker');
 IF NOT zasp_red_team_principal_ready('zasp_red_team_worker') OR NOT zasp_red_team_valid_input_artifact(organization_value,workspace_value,environment_value,input_value) OR input_value->>'reference'=reference_value THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='red team input artifact rejected';
 END IF;
 result_value:=zasp_red_team_finish_run_v38(organization_value,workspace_value,environment_value,run_value,worker_value,token_value,input_digest_value,verdict_value,objective_value,behavior_value,error_value,evidence_value,reference_value,key_value,version_value,checksum_value,size_value);
 UPDATE zasp_red_team_attempts SET input_artifact=input_value WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(organization_value,workspace_value,environment_value,run_value,(result_value->>'attempt')::integer) AND input_artifact IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='red team input artifact conflict';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_risk_mutate(requested_operation text, requested_finding_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_idempotency_key text, expected_version bigint, requested_status text, requested_reason text, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    requested_intent jsonb;
    digest_value bytea;
    prior_digest bytea;
    prior_response jsonb;
    result_version bigint;
    result_body jsonb;
BEGIN
    LOCK TABLE "public"."zasp_risk_findings", "public"."zasp_workflow_idempotency", "public"."zasp_workflow_audit", "public"."zasp_workflow_receipts" IN ROW EXCLUSIVE MODE;
    PERFORM public.zasp_audit_exports_require_ready();
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" release JOIN "public"."zasp_schema_metadata" marker ON marker."key"='production_core_schema' AND marker."value"='production-recovery-v1' WHERE release."version"=27 AND release."name"='production_recovery' AND NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" later WHERE later."version">60)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='risk projection release unavailable';
    END IF;
    IF requested_operation NOT IN ('updateFinding','acceptFindingRisk') OR expected_version<1
       OR length(requested_idempotency_key) NOT BETWEEN 16 AND 128
       OR requested_finding_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_principal_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_operation='updateFinding' AND (requested_status NOT IN ('open','under_review','resolved') OR requested_reason IS NOT NULL)
       OR requested_operation='acceptFindingRisk' AND (requested_status<>'accepted' OR length(requested_reason) NOT BETWEEN 1 AND 512) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid risk mutation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_risk_findings" AS candidate WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "public"."zasp_risk_finding_visible"(candidate)) THEN
        RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='risk finding missing';
    END IF;
    requested_intent := jsonb_build_object('resource_id',requested_finding_id,'expected_version',expected_version,'body',CASE WHEN requested_operation='updateFinding' THEN jsonb_build_object('status',requested_status) ELSE jsonb_build_object('reason',requested_reason) END);
    PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key),0));
    digest_value := digest(convert_to(requested_intent::text,'UTF8'),'sha256');
    SELECT "request_digest","response" INTO prior_digest,prior_response FROM "public"."zasp_workflow_idempotency"
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id
       AND "principal_id"=requested_principal_id AND "operation"=requested_operation AND "idempotency_key"=requested_idempotency_key;
    IF FOUND THEN
        IF prior_digest<>digest_value THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='idempotency conflict'; END IF;
        PERFORM public.zasp_audit_exports_require_ready(); RETURN prior_response||jsonb_build_object('replayed',true);
    END IF;
    UPDATE "public"."zasp_risk_findings" AS candidate SET "status"=requested_status,"acceptance_reason"=CASE WHEN requested_operation='acceptFindingRisk' THEN requested_reason ELSE NULL END,"version"="version"+1,"updated_at"=transaction_timestamp()
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "version"=expected_version AND "public"."zasp_risk_finding_visible"(candidate)
     RETURNING "version" INTO result_version;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='risk finding version conflict'; END IF;
    result_body := "public"."zasp_risk_finding_get"(requested_finding_id,requested_organization_id,requested_workspace_id,requested_environment_id);
    prior_response := jsonb_build_object('body',result_body,'version',result_version,'audit_id',requested_audit_id,'correlation_id',requested_correlation_id,'replayed',false);
    IF requested_receipt_id IS NOT NULL THEN prior_response:=prior_response||jsonb_build_object('receipt_id',requested_receipt_id); END IF;
    INSERT INTO "public"."zasp_workflow_audit" ("organization_id","workspace_id","environment_id","audit_id","correlation_id","principal_id","operation","resource_kind","resource_id","resource_version") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_audit_id,requested_correlation_id,requested_principal_id,requested_operation,'finding',requested_finding_id,result_version);
    INSERT INTO "public"."zasp_workflow_idempotency" ("organization_id","workspace_id","environment_id","principal_id","operation","idempotency_key","request_digest","response","receipt_semantics") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key,digest_value,prior_response-'replayed',CASE WHEN requested_receipt_id IS NULL THEN 'receiptless_incompatible' ELSE 'receipt_backed' END);
    IF requested_receipt_id IS NOT NULL THEN
        INSERT INTO "public"."zasp_workflow_receipts" ("organization_id","workspace_id","environment_id","principal_id","receipt_id","operation","idempotency_key","intent","result","resource_kind","resource_id","resource_version","audit_id","correlation_id") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_receipt_id,requested_operation,requested_idempotency_key,requested_intent,result_body,'finding',requested_finding_id,result_version,requested_audit_id,requested_correlation_id);
    END IF;
    PERFORM public.zasp_audit_exports_require_ready(); RETURN prior_response;
END;
$function$

CREATE OR REPLACE FUNCTION public.zasp_workflow_mutate(mutation text, requested_kind text, requested_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_operation text, requested_idempotency_key text, expected_version bigint, requested_intent jsonb, requested_body jsonb, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    mutation_response jsonb;
    existing_receipt_id text;
BEGIN
    LOCK TABLE "public"."zasp_workflow_idempotency" IN ROW EXCLUSIVE MODE;
    PERFORM public.zasp_audit_exports_require_ready();
    IF NOT EXISTS (
        SELECT 1
          FROM "public"."zasp_schema_versions" AS release
          JOIN "public"."zasp_schema_metadata" AS schema_marker
            ON schema_marker."key" = 'production_core_schema'
           AND schema_marker."value" = 'production-recovery-v1'
         WHERE release."version" = 27
           AND release."name" = 'production_recovery'
           AND NOT EXISTS (
               SELECT 1 FROM "public"."zasp_schema_versions" AS later_release
                WHERE later_release."version" > 60
           )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance release unavailable';
    END IF;
    IF requested_receipt_id IS NOT NULL AND requested_receipt_id <> '' AND length(requested_receipt_id) > 128 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'invalid workflow receipt';
    END IF;
    mutation_response := "public"."zasp_workflow_mutate_v3"(
        mutation, requested_kind, requested_id,
        requested_organization_id, requested_workspace_id, requested_environment_id,
        requested_principal_id, requested_operation, requested_idempotency_key,
        expected_version, requested_intent, requested_body, requested_audit_id, requested_correlation_id
    );
    existing_receipt_id := mutation_response ->> 'receipt_id';
    IF existing_receipt_id IS NOT NULL THEN
        PERFORM public.zasp_audit_exports_require_ready(); RETURN mutation_response;
    END IF;
    IF requested_receipt_id IS NULL OR requested_receipt_id = '' THEN
        UPDATE "public"."zasp_workflow_idempotency"
           SET "receipt_semantics" = 'receiptless_incompatible'
         WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
           AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
           AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key
           AND NULLIF("response" ->> 'receipt_id', '') IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
        END IF;
        PERFORM public.zasp_audit_exports_require_ready(); RETURN mutation_response;
    END IF;
    INSERT INTO "public"."zasp_workflow_receipts" (
        "organization_id", "workspace_id", "environment_id", "principal_id", "receipt_id",
        "operation", "idempotency_key", "intent", "result", "resource_kind", "resource_id",
        "resource_version", "audit_id", "correlation_id"
    ) VALUES (
        requested_organization_id, requested_workspace_id, requested_environment_id, requested_principal_id, requested_receipt_id,
        requested_operation, requested_idempotency_key, requested_intent, mutation_response -> 'body', requested_kind, requested_id,
        (mutation_response ->> 'version')::bigint, mutation_response ->> 'audit_id', mutation_response ->> 'correlation_id'
    );
    mutation_response := mutation_response || jsonb_build_object('receipt_id', requested_receipt_id);
    UPDATE "public"."zasp_workflow_idempotency"
       SET "response" = mutation_response - 'replayed',
           "receipt_semantics" = 'receipt_backed'
     WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
       AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
       AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
    END IF;
    PERFORM public.zasp_audit_exports_require_ready(); RETURN mutation_response;
END;
$function$
